-- ----------------------------
-- Table structure for invest_stock_pool
-- ----------------------------
DROP TABLE IF EXISTS `invest_stock_pool`;
CREATE TABLE `invest_stock_pool` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `stock_code` varchar(20) NOT NULL COMMENT '股票代码',
  `pool_type` enum('quality','tech_vc') NOT NULL COMMENT '质量优选/科技风投',
  `memo` text COMMENT '投资逻辑备注',
  `target_price` decimal(10,2) DEFAULT NULL COMMENT '目标价',
  `status` enum('watching','holding','exited') DEFAULT 'watching',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_pool_code` (`stock_code`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='龙江投资股票池';

