INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1041, 4, 1040, 'K-Means 聚类', NULL, NULL, 0, 3, 0, '2026-05-15 18:18:34');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1042, 4, 1040, '层次聚类', NULL, NULL, 1, 3, 0, '2026-05-15 18:18:34');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1050, 4, 1000, '神经网络与深度学习', NULL, NULL, 4, 2, 0, '2026-05-15 18:18:34');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1051, 106, NULL, '《投资中最简单的事》核心知识体系', '本书是邱国鹭对其多年价值投资实践的系统总结,围绕\"投资核心理念 → 分析框架 → 风险管理 → 策略与周期 → 心理与智慧\"五大支柱,讨论投资中真正重要、可执行、并且不变的事情。', '价值投资 = 在估值合理或低估的位置,买入具有持续竞争优势的好公司,长期持有获取企业内在价值增长的收益。', 0, 1, 0, '2026-05-15 18:35:47');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1052, 106, 1051, '投资核心理念', '本章讨论价值投资的底层世界观:重视估值、坚持便宜、敢于逆向。强调投资真正难的不是技巧,而是认知与坚持。', '便宜+优质+逆向 = 长期超额收益的三个最朴素来源。', 0, 2, 0, '2026-05-15 18:35:47');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1053, 106, 1052, '价值投资与成长投资', '比较两种主流投资理念,价值与成长并非对立,而是\"算账方式\"不同。', '价值看现金流折现,成长看复合增长;最终都要回到企业内在价值。', 0, 3, 0, '2026-05-15 18:35:47');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1054, 106, 1053, '价值投资的本质与优势', '价值投资强调以低于内在价值的价格买入,赚取价值回归与企业成长两份收益。它的优势在于安全边际显著、对认知要求清晰、长期复利更稳定。', NULL, 0, 4, 0, '2026-05-15 18:35:47');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1055, 106, 1053, '成长投资的特点与挑战', '成长投资追求高增长带来的估值与利润双升;挑战在于增长难以持续、估值容易透支、回撤往往剧烈,需要对行业判断极准。', NULL, 1, 4, 0, '2026-05-15 18:35:47');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1056, 106, 1053, '价值投资与成长投资的殊途同归', '无论价值还是成长,最终核心都是\"以合理价格买入优秀企业\";伟大公司终将在某一阶段同时具备\"便宜\"与\"成长\"两种属性。', NULL, 2, 4, 0, '2026-05-15 18:35:47');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1057, 106, 1052, '便宜是硬道理', '强调估值是投资中唯一可以\"事前把握\"的变量,低估值天然提供安全边际。', '如果不知道未来,至少要知道现在不贵。', 1, 3, 0, '2026-05-15 18:35:47');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1058, 106, 1057, '估值是投资中最可把握的要素', '未来很难预测,但当前的 PE、PB、股息率、自由现金流收益率是确定的;在不确定中找确定,先从估值开始。', NULL, 0, 4, 0, '2026-05-15 18:35:47');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1059, 106, 1057, '低估值提供安全边际', '估值低意味着即便判断有误,亏损幅度也有限;估值高则错一次就可能腰斩——这是非对称的风险收益。', NULL, 1, 4, 0, '2026-05-15 18:35:47');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1060, 106, 1057, '价值股长期跑赢成长股是规律', '全球长期数据(法马、夏普等学者研究)均显示,低估值组合长期跑赢高估值组合,这是市场对\"风险溢价\"与\"过度乐观\"的修正。', NULL, 2, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1061, 106, 1052, '人弃我取与逆向投资', '讨论逆向投资的本质、关键条件以及在哪些行业更适用。', '贪婪与恐惧的相反端,往往是赔率最高的时刻。', 2, 3, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1062, 106, 1061, '逆向投资是品格与超额收益来源', '逆向投资本质上是对人性弱点的克服:它需要在群体悲观时仍能独立判断,赚取的是市场情绪与基本面的偏差收益。', NULL, 0, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1063, 106, 1061, '逆向投资的三个关键条件', '1) 基本面未恶化只是情绪杀估值;2) 公司不会破产、行业不会消失;3) 有足够时间等待价值回归。', NULL, 1, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1064, 106, 1061, '逆向投资的行业适用性', '周期股、消费龙头、品牌护城河行业适合逆向;商业模式正在崩坏、技术被替代的行业不适合逆向(可能是价值陷阱)。', NULL, 2, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1065, 106, 1051, '投资分析框架', '把投资抽象为可重复执行的分析流程:回答\"为什么便宜\"\"为什么好\"\"为什么现在买\"三个问题,辅以波特五力、杜邦、估值三套工具,并叠加行业选择。', '估值 + 品质 + 时机,缺一不可。', 1, 2, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1066, 106, 1065, '投资的三个基本问题', '把任何一个买入决定,都压缩成 3 个必答题。回答不了任意一题,就不该下单。', '估值 + 品质 + 时机,缺一不可。', 0, 3, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1067, 106, 1066, '问题1: 估值 (为什么便宜)', '回答\"为什么便宜\":是市场偏见、行业错配、短期利空,还是基本面已经永久受损?只有前者才值得买入。', NULL, 0, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1068, 106, 1066, '问题2: 品质 (为什么好)', '回答\"为什么好\":公司的护城河、ROIC、管理层、长期空间、商业模式可持续性。', NULL, 1, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1069, 106, 1066, '问题3: 时机 (为什么现在买)', '回答\"为什么现在买\":催化剂、行业拐点、估值底部信号——避免\"价值股一拿三年还在跌\"。', NULL, 2, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1070, 106, 1065, '投资分析的基本工具', '三套足以应付 90% 场景的基础工具。', '工具不是用来炫技,而是用来落地三个基本问题。', 1, 3, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1071, 106, 1070, '波特五力分析', '用于评估行业竞争格局:现有竞争者、潜在进入者、替代品、上游议价、下游议价。判断\"为什么好\"的核心工具之一。', NULL, 0, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1072, 106, 1070, '杜邦分析', '把 ROE 拆解为净利率 × 周转率 × 杠杆,识别公司盈利能力到底来自哪里、可持续性如何。', NULL, 1, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1073, 106, 1070, '估值分析', 'PE、PB、PS、DCF、股息折现等多套估值方法交叉验证,避免单一指标失真。', NULL, 2, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1074, 106, 1065, '行业选择与竞争格局', '选对行业比选对公司更重要,行业的竞争格局决定了平均回报上限。', '行业β > 公司α,选对赛道是大概率事件的开始。', 2, 3, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1075, 106, 1074, '好行业的标准', '需求稳定、行业增速合理、竞争格局清晰、龙头优势可持续、ROIC 高于资金成本。', NULL, 0, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1076, 106, 1074, '行业集中度与投资回报', '集中度提升的行业,龙头通常获得超额回报;过度分散且无品牌护城河的行业难出长牛股。', NULL, 1, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1077, 106, 1074, '\"数月亮\"策略', '选行业时\"数月亮\"而不是\"数星星\":只投行业里能数得过来、最大、最亮的几个龙头。', NULL, 2, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1078, 106, 1051, '投资风险与管理', '辨别价值陷阱与成长陷阱、区分真假风险、运用安全边际,并理解价值投资本身的局限,知道何时止损。', '风险管理的核心,不是预测风险,而是为意外预留缓冲——这就是安全边际。', 2, 2, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1079, 106, 1078, '价值陷阱与成长陷阱', '便宜不等于好,高成长也不等于好;两类陷阱毁掉的财富甚至超过牛市赚到的。', '价值陷阱:便宜得有原因;成长陷阱:成长被透支。', 0, 3, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1080, 106, 1079, '价值陷阱的常见类型', '夕阳行业、被技术颠覆的行业、周期顶点的强周期股、公司治理崩坏的低估值股——便宜只是表象,内在价值还在持续下滑。', NULL, 0, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1081, 106, 1079, '成长陷阱的常见类型', '伪需求、伪壁垒、风口型创业、估值已透支未来 5-10 年增长的高估值成长股。', NULL, 1, 4, 0, '2026-05-15 18:35:48');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1082, 106, 1079, '两类陷阱的共性', '都是把短期信号当作长期规律,缺乏对商业模式与护城河的本质审视。', NULL, 2, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1083, 106, 1078, '真假风险与安全边际', '市场上每天讨论的\"风险\",大多是噪声;真正的风险是\"本金永久性损失\"。', '波动 ≠ 风险;不可恢复的损失才是风险。', 1, 3, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1084, 106, 1083, '风险的多种维度', '包括估值风险、流动性风险、行业风险、公司治理风险、宏观系统风险。理解风险的多维度才能恰当配置。', NULL, 0, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1085, 106, 1083, '安全边际的特点', '在价格 vs 价值之间留出缓冲;留得越宽,容错越大。', NULL, 1, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1086, 106, 1083, '通过安全边际管理风险', '通过低估值买入 + 分散持仓 + 避免杠杆,把不可控变成可控。', NULL, 2, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1087, 106, 1078, '止损与价值投资局限性', '价值投资不是\"死扛\";同样有其适用边界。', '持有的前提是基本面没变;基本面变了,再便宜也要卖。', 2, 3, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1088, 106, 1087, '止损与卖出原则', '1) 基本面变坏;2) 投资逻辑被证伪;3) 找到性价比更高的标的;4) 估值显著高估。', NULL, 0, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1089, 106, 1087, '价值投资的四个基本条件与局限性', '条件:有效市场失灵、自由现金流可估算、企业可分析、投资期限够长。局限:在牛市后期跑不赢风口,在情绪市可能持续跑输。', NULL, 1, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1090, 106, 1051, '投资策略与市场周期', '理解四种周期、三种杠杆与板块轮动逻辑;在中国经济\"新常态\"背景下,识别未来 10 年的投资路向。', '策略服从周期,资金跟随杠杆;新常态下,优质龙头与消费/科技确定性更高。', 3, 2, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1091, 106, 1090, '四种周期与三种杠杆', '经济与资本市场存在四种周期:产能、库存、信贷、情绪;三种杠杆:经营、财务、估值。', '周期决定方向,杠杆决定弹性。', 0, 3, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1092, 106, 1091, '四种周期的演变顺序', '情绪周期 → 信贷周期 → 库存周期 → 产能周期。前置周期决定后置周期的运行节奏。', NULL, 0, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1093, 106, 1091, '三种杠杆与板块轮动', '估值杠杆驱动金融股,财务杠杆驱动地产/周期股,经营杠杆驱动消费/制造龙头。', NULL, 1, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1094, 106, 1091, '周期分析的应用与启示', '在不同周期阶段配置不同杠杆敏感度的资产,可以平滑组合曲线、提高夏普比。', NULL, 2, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1095, 106, 1090, '未来10年投资路向', '在中国经济\"新常态\"下,寻找仍能跑出 10x 的领域。', '增速换挡,从总量为王进入结构为王。', 1, 3, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1096, 106, 1095, '中国经济的\"新常态\"', 'GDP 增速放缓、消费占比提升、服务业崛起、产业升级与高质量发展并行。', NULL, 0, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1097, 106, 1095, '\"新常态\"下的投资思路', '聚焦优质龙头、低估值消费、品牌护城河、技术升级中的国产替代。', NULL, 1, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1098, 106, 1095, '\"新常态\"下的投资方向', '大消费、医药健康、先进制造、半导体国产替代、新能源,以及具备出海能力的中国制造龙头。', NULL, 2, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1099, 106, 1051, '投资心理学与智慧', '梳理常见心理误区,提炼经典投资格言,用\"树动 / 风动 / 心动\"框架理解短中长期股价驱动因素。', '战胜市场,先战胜自己。', 4, 2, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1100, 106, 1099, '投资者常见的心理误区', '行为金融视角:三类高发心理偏差,在熊牛切换时尤其致命。', '市场不是错的,错的是被偏差扭曲的我们。', 0, 3, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1101, 106, 1100, '过度自信与仓位思维', '高估自身判断,忽视概率思维;\"all in\" 一只票或一个赛道,放大错误的代价。', NULL, 0, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1102, 106, 1100, '锚固偏见与短期趋势长期化', '锚定历史成本或最近高点,把短期趋势外推成长期规律,在牛市顶点最容易犯。', NULL, 1, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1103, 106, 1100, '亏损厌恶症与羊群效应', '对亏损的痛苦感是收益喜悦的 2 倍,促使人在底部割肉、在顶点追高;羊群效应放大这一过程。', NULL, 2, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1104, 106, 1099, '投资智慧与格言', '三句经典格言,精炼了价值投资的核心精神。', '经典之所以经典,因为反复奏效。', 1, 3, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1105, 106, 1104, '\"在别人恐惧时贪婪\"的真义', '巴菲特名言。真正含义不是\"无脑抄底\",而是\"在被情绪杀价的好公司上加仓\"。', NULL, 0, 4, 0, '2026-05-15 18:35:49');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1106, 106, 1104, '\"留得青山在\"与风险区分', '区分\"绝对损失\"和\"机会成本损失\";前者要竭力避免,后者必然存在。', NULL, 1, 4, 0, '2026-05-15 18:35:50');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1107, 106, 1104, '\"二鸟在林不如一鸟在手\"的启示', '宁选确定的好公司,不去赌不确定的暴利标的——优势叠加比单点突破更可持续。', NULL, 2, 4, 0, '2026-05-15 18:35:50');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1108, 106, 1099, '树动风动心动', '用三句话区分短中长期的股价驱动因素,帮助投资者建立时间维度感。', '股价 = 心动 × 风动 × 树动;期限越长,树动权重越大。', 2, 3, 0, '2026-05-15 18:35:50');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1109, 106, 1108, '短期: 心在动 (情绪博弈)', '短期股价由情绪与博弈主导,任何价格都可能合理或荒谬。', NULL, 0, 4, 0, '2026-05-15 18:35:50');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1110, 106, 1108, '中期: 风在动 (政策决定)', '中期由政策、行业景气与资金面驱动,体现\"风口\"逻辑。', NULL, 1, 4, 0, '2026-05-15 18:35:50');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1111, 106, 1108, '长期: 树在动 (基本面决定)', '长期最终回到企业基本面与现金流——树才是真正在长大的东西。', NULL, 2, 4, 0, '2026-05-15 18:35:50');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1112, 107, NULL, '《投资中最简单的事》核心知识体系', '本书是邱国鹭对其多年价值投资实践的系统总结,围绕\"投资核心理念 → 分析框架 → 风险管理 → 策略与周期 → 心理与智慧\"五大支柱,讨论投资中真正重要、可执行、并且不变的事情。', '价值投资 = 在估值合理或低估的位置,买入具有持续竞争优势的好公司,长期持有获取企业内在价值增长的收益。', 0, 1, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1113, 107, 1112, '投资核心理念', '本章讨论价值投资的底层世界观:重视估值、坚持便宜、敢于逆向。强调投资真正难的不是技巧,而是认知与坚持。', '便宜+优质+逆向 = 长期超额收益的三个最朴素来源。', 0, 2, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1114, 107, 1113, '价值投资与成长投资', '比较两种主流投资理念,价值与成长并非对立,而是\"算账方式\"不同。', '价值看现金流折现,成长看复合增长;最终都要回到企业内在价值。', 0, 3, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1115, 107, 1114, '价值投资的本质与优势', '价值投资强调以低于内在价值的价格买入,赚取价值回归与企业成长两份收益。它的优势在于安全边际显著、对认知要求清晰、长期复利更稳定。', NULL, 0, 4, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1116, 107, 1114, '成长投资的特点与挑战', '成长投资追求高增长带来的估值与利润双升;挑战在于增长难以持续、估值容易透支、回撤往往剧烈,需要对行业判断极准。', NULL, 1, 4, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1117, 107, 1114, '价值投资与成长投资的殊途同归', '无论价值还是成长,最终核心都是\"以合理价格买入优秀企业\";伟大公司终将在某一阶段同时具备\"便宜\"与\"成长\"两种属性。', NULL, 2, 4, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1118, 107, 1113, '便宜是硬道理', '强调估值是投资中唯一可以\"事前把握\"的变量,低估值天然提供安全边际。', '如果不知道未来,至少要知道现在不贵。', 1, 3, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1119, 107, 1118, '估值是投资中最可把握的要素', '未来很难预测,但当前的 PE、PB、股息率、自由现金流收益率是确定的;在不确定中找确定,先从估值开始。', NULL, 0, 4, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1120, 107, 1118, '低估值提供安全边际', '估值低意味着即便判断有误,亏损幅度也有限;估值高则错一次就可能腰斩——这是非对称的风险收益。', NULL, 1, 4, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1121, 107, 1118, '价值股长期跑赢成长股是规律', '全球长期数据(法马、夏普等学者研究)均显示,低估值组合长期跑赢高估值组合,这是市场对\"风险溢价\"与\"过度乐观\"的修正。', NULL, 2, 4, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1122, 107, 1113, '人弃我取与逆向投资', '讨论逆向投资的本质、关键条件以及在哪些行业更适用。', '贪婪与恐惧的相反端,往往是赔率最高的时刻。', 2, 3, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1123, 107, 1122, '逆向投资是品格与超额收益来源', '逆向投资本质上是对人性弱点的克服:它需要在群体悲观时仍能独立判断,赚取的是市场情绪与基本面的偏差收益。', NULL, 0, 4, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1124, 107, 1122, '逆向投资的三个关键条件', '1) 基本面未恶化只是情绪杀估值;2) 公司不会破产、行业不会消失;3) 有足够时间等待价值回归。', NULL, 1, 4, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1125, 107, 1122, '逆向投资的行业适用性', '周期股、消费龙头、品牌护城河行业适合逆向;商业模式正在崩坏、技术被替代的行业不适合逆向(可能是价值陷阱)。', NULL, 2, 4, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1126, 107, 1112, '投资分析框架', '把投资抽象为可重复执行的分析流程:回答\"为什么便宜\"\"为什么好\"\"为什么现在买\"三个问题,辅以波特五力、杜邦、估值三套工具,并叠加行业选择。', '估值 + 品质 + 时机,缺一不可。', 1, 2, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1127, 107, 1126, '投资的三个基本问题', '把任何一个买入决定,都压缩成 3 个必答题。回答不了任意一题,就不该下单。', '估值 + 品质 + 时机,缺一不可。', 0, 3, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1128, 107, 1127, '问题1: 估值 (为什么便宜)', '回答\"为什么便宜\":是市场偏见、行业错配、短期利空,还是基本面已经永久受损?只有前者才值得买入。', NULL, 0, 4, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1129, 107, 1127, '问题2: 品质 (为什么好)', '回答\"为什么好\":公司的护城河、ROIC、管理层、长期空间、商业模式可持续性。', NULL, 1, 4, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1130, 107, 1127, '问题3: 时机 (为什么现在买)', '回答\"为什么现在买\":催化剂、行业拐点、估值底部信号——避免\"价值股一拿三年还在跌\"。', NULL, 2, 4, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1131, 107, 1126, '投资分析的基本工具', '三套足以应付 90% 场景的基础工具。', '工具不是用来炫技,而是用来落地三个基本问题。', 1, 3, 0, '2026-05-15 18:47:53');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1132, 107, 1131, '波特五力分析', '用于评估行业竞争格局:现有竞争者、潜在进入者、替代品、上游议价、下游议价。判断\"为什么好\"的核心工具之一。', NULL, 0, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1133, 107, 1131, '杜邦分析', '把 ROE 拆解为净利率 × 周转率 × 杠杆,识别公司盈利能力到底来自哪里、可持续性如何。', NULL, 1, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1134, 107, 1131, '估值分析', 'PE、PB、PS、DCF、股息折现等多套估值方法交叉验证,避免单一指标失真。', NULL, 2, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1135, 107, 1126, '行业选择与竞争格局', '选对行业比选对公司更重要,行业的竞争格局决定了平均回报上限。', '行业β > 公司α,选对赛道是大概率事件的开始。', 2, 3, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1136, 107, 1135, '好行业的标准', '需求稳定、行业增速合理、竞争格局清晰、龙头优势可持续、ROIC 高于资金成本。', NULL, 0, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1137, 107, 1135, '行业集中度与投资回报', '集中度提升的行业,龙头通常获得超额回报;过度分散且无品牌护城河的行业难出长牛股。', NULL, 1, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1138, 107, 1135, '\"数月亮\"策略', '选行业时\"数月亮\"而不是\"数星星\":只投行业里能数得过来、最大、最亮的几个龙头。', NULL, 2, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1139, 107, 1112, '投资风险与管理', '辨别价值陷阱与成长陷阱、区分真假风险、运用安全边际,并理解价值投资本身的局限,知道何时止损。', '风险管理的核心,不是预测风险,而是为意外预留缓冲——这就是安全边际。', 2, 2, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1140, 107, 1139, '价值陷阱与成长陷阱', '便宜不等于好,高成长也不等于好;两类陷阱毁掉的财富甚至超过牛市赚到的。', '价值陷阱:便宜得有原因;成长陷阱:成长被透支。', 0, 3, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1141, 107, 1140, '价值陷阱的常见类型', '夕阳行业、被技术颠覆的行业、周期顶点的强周期股、公司治理崩坏的低估值股——便宜只是表象,内在价值还在持续下滑。', NULL, 0, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1142, 107, 1140, '成长陷阱的常见类型', '伪需求、伪壁垒、风口型创业、估值已透支未来 5-10 年增长的高估值成长股。', NULL, 1, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1143, 107, 1140, '两类陷阱的共性', '都是把短期信号当作长期规律,缺乏对商业模式与护城河的本质审视。', NULL, 2, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1144, 107, 1139, '真假风险与安全边际', '市场上每天讨论的\"风险\",大多是噪声;真正的风险是\"本金永久性损失\"。', '波动 ≠ 风险;不可恢复的损失才是风险。', 1, 3, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1145, 107, 1144, '风险的多种维度', '包括估值风险、流动性风险、行业风险、公司治理风险、宏观系统风险。理解风险的多维度才能恰当配置。', NULL, 0, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1146, 107, 1144, '安全边际的特点', '在价格 vs 价值之间留出缓冲;留得越宽,容错越大。', NULL, 1, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1147, 107, 1144, '通过安全边际管理风险', '通过低估值买入 + 分散持仓 + 避免杠杆,把不可控变成可控。', NULL, 2, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1148, 107, 1139, '止损与价值投资局限性', '价值投资不是\"死扛\";同样有其适用边界。', '持有的前提是基本面没变;基本面变了,再便宜也要卖。', 2, 3, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1149, 107, 1148, '止损与卖出原则', '1) 基本面变坏;2) 投资逻辑被证伪;3) 找到性价比更高的标的;4) 估值显著高估。', NULL, 0, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1150, 107, 1148, '价值投资的四个基本条件与局限性', '条件:有效市场失灵、自由现金流可估算、企业可分析、投资期限够长。局限:在牛市后期跑不赢风口,在情绪市可能持续跑输。', NULL, 1, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1151, 107, 1112, '投资策略与市场周期', '理解四种周期、三种杠杆与板块轮动逻辑;在中国经济\"新常态\"背景下,识别未来 10 年的投资路向。', '策略服从周期,资金跟随杠杆;新常态下,优质龙头与消费/科技确定性更高。', 3, 2, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1152, 107, 1151, '四种周期与三种杠杆', '经济与资本市场存在四种周期:产能、库存、信贷、情绪;三种杠杆:经营、财务、估值。', '周期决定方向,杠杆决定弹性。', 0, 3, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1153, 107, 1152, '四种周期的演变顺序', '情绪周期 → 信贷周期 → 库存周期 → 产能周期。前置周期决定后置周期的运行节奏。', NULL, 0, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1154, 107, 1152, '三种杠杆与板块轮动', '估值杠杆驱动金融股,财务杠杆驱动地产/周期股,经营杠杆驱动消费/制造龙头。', NULL, 1, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1155, 107, 1152, '周期分析的应用与启示', '在不同周期阶段配置不同杠杆敏感度的资产,可以平滑组合曲线、提高夏普比。', NULL, 2, 4, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1156, 107, 1151, '未来10年投资路向', '在中国经济\"新常态\"下,寻找仍能跑出 10x 的领域。', '增速换挡,从总量为王进入结构为王。', 1, 3, 0, '2026-05-15 18:47:54');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1157, 107, 1156, '中国经济的\"新常态\"', 'GDP 增速放缓、消费占比提升、服务业崛起、产业升级与高质量发展并行。', NULL, 0, 4, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1158, 107, 1156, '\"新常态\"下的投资思路', '聚焦优质龙头、低估值消费、品牌护城河、技术升级中的国产替代。', NULL, 1, 4, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1159, 107, 1156, '\"新常态\"下的投资方向', '大消费、医药健康、先进制造、半导体国产替代、新能源,以及具备出海能力的中国制造龙头。', NULL, 2, 4, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1160, 107, 1112, '投资心理学与智慧', '梳理常见心理误区,提炼经典投资格言,用\"树动 / 风动 / 心动\"框架理解短中长期股价驱动因素。', '战胜市场,先战胜自己。', 4, 2, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1161, 107, 1160, '投资者常见的心理误区', '行为金融视角:三类高发心理偏差,在熊牛切换时尤其致命。', '市场不是错的,错的是被偏差扭曲的我们。', 0, 3, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1162, 107, 1161, '过度自信与仓位思维', '高估自身判断,忽视概率思维;\"all in\" 一只票或一个赛道,放大错误的代价。', NULL, 0, 4, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1163, 107, 1161, '锚固偏见与短期趋势长期化', '锚定历史成本或最近高点,把短期趋势外推成长期规律,在牛市顶点最容易犯。', NULL, 1, 4, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1164, 107, 1161, '亏损厌恶症与羊群效应', '对亏损的痛苦感是收益喜悦的 2 倍,促使人在底部割肉、在顶点追高;羊群效应放大这一过程。', NULL, 2, 4, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1165, 107, 1160, '投资智慧与格言', '三句经典格言,精炼了价值投资的核心精神。', '经典之所以经典,因为反复奏效。', 1, 3, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1166, 107, 1165, '\"在别人恐惧时贪婪\"的真义', '巴菲特名言。真正含义不是\"无脑抄底\",而是\"在被情绪杀价的好公司上加仓\"。', NULL, 0, 4, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1167, 107, 1165, '\"留得青山在\"与风险区分', '区分\"绝对损失\"和\"机会成本损失\";前者要竭力避免,后者必然存在。', NULL, 1, 4, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1168, 107, 1165, '\"二鸟在林不如一鸟在手\"的启示', '宁选确定的好公司,不去赌不确定的暴利标的——优势叠加比单点突破更可持续。', NULL, 2, 4, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1169, 107, 1160, '树动风动心动', '用三句话区分短中长期的股价驱动因素,帮助投资者建立时间维度感。', '股价 = 心动 × 风动 × 树动;期限越长,树动权重越大。', 2, 3, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1170, 107, 1169, '短期: 心在动 (情绪博弈)', '短期股价由情绪与博弈主导,任何价格都可能合理或荒谬。', NULL, 0, 4, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1171, 107, 1169, '中期: 风在动 (政策决定)', '中期由政策、行业景气与资金面驱动,体现\"风口\"逻辑。', NULL, 1, 4, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1172, 107, 1169, '长期: 树在动 (基本面决定)', '长期最终回到企业基本面与现金流——树才是真正在长大的东西。', NULL, 2, 4, 0, '2026-05-15 18:47:55');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1173, 108, NULL, '《投资中最简单的事》核心知识体系', '本书是邱国鹭22年投资经验的总结，强调以实业眼光做投资，倡导价值投资和逆向投资理念。书中将选股简化为估值、品质、时机三要素，主张在不确定的市场中把握简单可行的投资法则。', '价值投资指以五毛钱价格购买未来价值一元钱的企业（P0<<V0<Vn），核心是寻找“价格被低估的好公司”。', 0, 1, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1174, 108, 1173, '投资理念', '本书核心理念部分，阐述以实业眼光进行投资的思维方式，强调逆向思维和估值的重要性。', '以做实业的心态做投资，把二级市场股票当作一级市场股权投资来分析。', 0, 2, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1175, 108, 1174, '以实业眼光投资', '强调投资股票应像做实业一样审视企业，考察商业模式、现金流和竞争格局。', '投资前先问这是不是一门好生意，门槛高不高，现金流好不好。', 0, 3, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1176, 108, 1175, '好生意的标准', '好生意有两个标准：一是做的事情别人做不了；二是做的事情可以自己重复做。前者是门槛，后者是可复制性。', '门槛决定利润率，成长可复制性决定增速。宁可要门槛低的增长，也不要没门槛的高增长。', 0, 4, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1177, 108, 1175, '现金流分析', '做生意的最终目的是赚取现金流。电影业现金流差（先支出后回收），房地产现金流好（预售制）。', '现金流状况决定企业抗风险能力和持续经营能力。', 1, 4, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1178, 108, 1175, '竞争格局判断', '行业集中度持续提高易出牛股（先发优势）；行业分散则门槛不高，各领风骚两三年。', '高门槛行业供给受限，竞争有序，利于企业盈利增长。', 2, 4, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1179, 108, 1175, '定价权重要性', '有定价权的公司才是好公司。电影业定价权在导演演员手中，故制片方难赚钱；迪士尼因卡通形象不涨片酬而屹立百年。', '定价权是核心竞争力的最终体现。', 3, 4, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1180, 108, 1174, '逆向投资思维', '阐述逆向投资的重要性和实践方法，强调人弃我取的逆向思维是成功投资的关键。', '在别人恐惧时贪婪，在别人贪婪时恐惧。', 1, 3, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1181, 108, 1180, '逆向投资的必要性', '成功的投资大师如巴菲特、索罗斯、邓普顿都具有超强的逆向思维能力。', 'A股情绪波动易走极端，爆炒后常暴跌，对“手脚不快”的人“人多的地方不去”是至理名言。', 0, 4, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1182, 108, 1180, '逆向投资的适用范围', '逆向投资适用于高门槛行业中的优质公司，以及周期性行业的阶段性底部。', '并非所有下跌都值得买入，需要判断下跌是因为基本面恶化还是市场情绪。', 1, 4, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1183, 108, 1180, '逆向与趋势的关系', '逆向投资不是简单的反向操作，而是独立判断基础上的逆向行动。', '投资需要逆向思维，但前提是独立客观的分析。', 2, 4, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1184, 108, 1174, '便宜才是硬道理', '强调估值是投资中最简单、最可靠的判断标准，再好的公司也要有合理价格。', '即使普通公司，只要足够便宜也会有丰厚回报；发现“价格合理的伟大公司”难度远超“价格被低估的普通公司”。', 2, 3, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1185, 108, 1184, '估值的重要性', '把选股简化为估值、品质、时机三个要素，淡化时机（难把握），重点在估值。', '寻找“便宜的好公司”是相对简单的问题。', 0, 4, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1186, 108, 1184, '价值与成长的统一', '价值投资P0<<V0<Vn，成长投资P0<V0<<Vn，两者殊途同归，都希望五毛钱买一元价值。', '价值投资更易掌握，因为分析现在比预测未来容易。', 1, 4, 0, '2026-05-15 18:55:07');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1187, 108, 1184, '安全边际', '买得便宜是最大的安全边际，为判断错误预留容错空间。', '没有安全边际的投资如同没有护城河的城堡。', 2, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1188, 108, 1173, '投资方法', '介绍实用的投资分析工具和方法，包括波特五力、杜邦分析等简单工具的应用。', '用简单的法则和工具分析复杂的投资问题，把不能把握的因素留给运气和概率。', 1, 2, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1189, 108, 1188, '三个基本问题', '投资需要回答三个核心问题：为什么买、买什么、以什么价格买。', '投资的本质是回答这三个基本问题。', 0, 3, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1190, 108, 1189, '行业选择方法', '利用波特五力分析行业格局演变、技术进步、上下游变迁。', '弄清决定行业竞争胜负的关键因素是什么。', 0, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1191, 108, 1189, '公司分析方法', '用杜邦分析弄清什么样的公司算“好公司”，什么样的价格是“便宜”。', '不同行业“好公司”的标准不同。', 1, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1192, 108, 1189, '估值工具应用', '对餐饮业看回头客、翻台率、坪效；对零售业看同店增长、开店速度、应收账款。', '针对行业特性灵活运用估值工具。', 2, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1193, 108, 1188, '月亮与星星', '强调在竞争激烈的行业中应选择已经胜出的龙头公司，而非押注黑马。', '宁数月亮不数星星，月亮是行业赢家，星星是行业竞争者。', 1, 3, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1194, 108, 1193, '胜而后求战', '百舸争流的行业增长再快也难找投资标的，应等待行业“内战”结束、赢家产生后再投资。', '投资于行业格局稳定后的龙头企业。', 0, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1195, 108, 1193, '行业拐点判断', '白色家电2005年行业大洗牌后，小厂退出，龙头企业规模、渠道、成本、品牌优势扩大。', '行业拐点之后龙头才能持续盈利。', 1, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1196, 108, 1193, '护城河识别', '每三四年就得重挖的护城河不是真护城河；只有难以复制的独占资源、品牌、专利、寡头地位才是护城河。', '护城河要经得起时间考验。', 2, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1197, 108, 1188, '经验的应用', '强调投资经验来自实践积累，但需要不断更新和修正。', '经验像旧衣服，要根据时代变化调整穿着方式。', 2, 3, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1198, 108, 1197, '规律与人性的关系', '虽然科技进步日新月异，但人性中贪婪和恐惧不变，规律性的东西不会过时。', '每隔几年市场就会疯狂一次，但历史总在重复。', 0, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1199, 108, 1197, '能力圈边界', '认识自己的能力边界：不擅长预测未来突破，擅长总结过去规律；擅长在变化中找不变。', '只在能力圈内投资。', 1, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1200, 108, 1173, '投资风险', '分析投资中常见的陷阱类型，强调安全边际的重要性及其局限性。', '投资的第一规则是能够持续玩下去，再好的投资理念也要控制风险。', 2, 2, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1201, 108, 1200, '价值陷阱', '价值陷阱指便宜但基本面持续恶化的公司，看似低估实则高估。', '便宜不是买入的理由，基本面才是。', 0, 3, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1202, 108, 1201, '陷阱的特征', '价值陷阱通常是夕阳行业、增长已尽的成熟行业、或被技术淘汰的公司。', '低估值可能反映的是永久性衰退。', 0, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1203, 108, 1201, '识别方法', '需要区分“假便宜”和“真低估”，关键是判断公司未来现金流是否持续。', '买入前必须确认公司质地。', 1, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1204, 108, 1200, '成长陷阱', '成长陷阱指高增长预期但实际无法兑现的公司，A股市场最常见的陷阱。', '高增长不等于高回报，成长是未来的，难预测。', 1, 3, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1205, 108, 1204, '常见类型', '技术淘汰、行业门槛低、现金流差、依赖单一产品或客户的公司易出现成长陷阱。', '手游行业一将功成万骨枯，单机游戏产品生命周期短。', 0, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1206, 108, 1204, '识别方法', '警惕高估值、依赖热点概念、无持续竞争优势支撑的高增长。', '成长需要门槛保护，否则难以持续。', 1, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1207, 108, 1200, '风险与安全边际', '阐述真假风险的区分方法，强调安全边际是价值投资的保护伞。', '真正的风险是永久性损失本金的可能性，而非短期波动。', 2, 3, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1208, 108, 1207, '真假风险辨别', '真假风险：短期波动是真风险还是假风险？长期持有高分红股票风险反而较低。', '波动不等于风险，本金永久损失才是真风险。', 0, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1209, 108, 1207, '安全边际作用', '安全边际为判断错误预留空间，即使正确也提供超额收益。', '没有安全边际的投资如同在悬崖边行走。', 1, 4, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1210, 108, 1173, '投资策略', '讨论市场周期、行业轮动策略，以及对中国经济转型期投资方向的判断。', '投资策略需要结合宏观周期和行业特性，在正确时机做出正确配置。', 3, 2, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1211, 108, 1210, '周期与杠杆', '分析四种周期（政策周期、经济周期、盈利周期、情绪周期）和三种杠杆（财务杠杆、经营杠杆、估值杠杆）的关系。', '周期定位决定仓位，行业配置决定方向。', 0, 3, 0, '2026-05-15 18:55:08');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1212, 108, 1211, '周期分析方法', '政策底领先市场底领先经济底，需要在周期不同阶段调整策略。', '周期分析是择时的基础。', 0, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1213, 108, 1211, '杠杆运用', '三种杠杆在不同阶段作用不同，需要根据周期位置选择合适策略。', '杠杆放大收益也放大风险。', 1, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1214, 108, 1210, '行业配置策略', '强调超额收益主要来自行业配置，正确的行业选择比个股选择更重要。', '在正确的时间做正确的事。', 1, 3, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1215, 108, 1214, '配置原则', '在行业景气度高、估值合理时加大配置，在行业拐点后减持。', '行业轮动有其规律可循。', 0, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1216, 108, 1214, '超额收益来源', 'A股市场行业间差异远大于个股间差异，行业配置是超额收益的主要来源。', '选对行业就成功了一半。', 1, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1217, 108, 1210, '中国机遇与挑战', '分析中国经济转型期的投资机会和风险。', '投资需要顺势而为，把握时代背景。', 2, 3, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1218, 108, 1217, '转型期特征', '经济从高速增长转向高质量发展，传统行业整合，新兴行业崛起。', '投资方向要顺应经济转型趋势。', 0, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1219, 108, 1217, '机遇识别', '消费升级、技术创新、全球化布局等领域存在长期机会。', '在变化中寻找不变的趋势。', 1, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1220, 108, 1173, '投资心理学', '深入分析投资者常见的人性弱点和心理误区，强调认识自我、控制情绪的重要性。', '投资最终反映的是个人的真实性情和价值观，健康的心态是长期成功的基础。', 4, 2, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1221, 108, 1220, '人性弱点', '分析投资者常见的心理误区，包括过度自信、从众心理、损失厌恶等。', '人性弱点是投资的大敌，需要通过纪律和制度来克服。', 0, 3, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1222, 108, 1221, '损失厌恶', '投资者往往对亏损的厌恶超过对盈利的喜悦，导致过早卖出盈利股、死守亏损股。', '要学会让利润奔跑、截断亏损。', 0, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1223, 108, 1221, '过度自信', '投资者往往高估自己的判断能力，低估市场风险。', '承认自己的局限性是进步的开始。', 1, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1224, 108, 1221, '从众心理', '投资者容易跟随市场情绪，在高点买入、低点卖出。', '逆向思维需要强大的心理支撑。', 2, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1225, 108, 1220, '认知偏差', '分析投资者常见的认知错误，如后视镜思维、锚定效应等。', '投资中的大部分错误来自认知偏差而非信息不足。', 1, 3, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1226, 108, 1225, '后视镜思维', '投资者习惯用过去的市场表现预测未来，忽视环境变化。', '过去的表现不代表未来。', 0, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1227, 108, 1225, '这次不同了', '历史上每次泡沫都有“这次不同了”的声音，结果证明都是对历史的健忘。', '人性亘古不变，市场周期循环往复。', 1, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1228, 108, 1225, '锚定效应', '投资者容易以买入价或历史高点作为参考，忽视公司基本面的变化。', '投资决策应以价值为锚，而非以价格为锚。', 2, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1229, 108, 1220, '心理修炼', '强调投资成功需要良好的心理素质，包括耐心、纪律、独立思考等。', '投资到最后反映的是个人的真实性情和价值观。', 2, 3, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1230, 108, 1229, '延迟满足', '成功投资需要抵制即时满足的诱惑，愿意等待长期回报。', '能延迟满足的人更可能在投资中成功。', 0, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1231, 108, 1229, '知易行难', '认识人性弱点容易，克服它难。投资需要纪律和修行。', '知道不等于做到，需要长期修炼。', 1, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1232, 108, 1229, '心态管理', '保持peace of mind，远离喧嚣，独立思考。', '心境的平和是做出正确决策的基础。', 2, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1233, 108, 1173, '投资心法', '汇总书中反复强调的核心投资原则和箴言。', '简单可行的投资法则长期坚持，比复杂的方法更有效。', 5, 2, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1234, 108, 1233, '四大原则', '本书强调的四个核心投资原则：便宜是硬道理、定价权是核心竞争力、胜而后求战、人弃我取。', '这些原则经许多成功投资人长期验证，触及投资本质。', 0, 3, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1235, 108, 1234, '便宜是硬道理', '即使普通公司，只要足够便宜也会有丰厚回报。', '买得便宜是最大的保护。', 0, 4, 0, '2026-05-15 18:55:09');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1236, 108, 1234, '定价权是核心', '有核心竞争力的公司要么可以不断复制，要么别人无法复制。', '定价权带来超额利润。', 1, 4, 0, '2026-05-15 18:55:10');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1237, 108, 1234, '胜而后求战', '投资行业赢家而非押注黑马，行业内战后介入。', '赢家有护城河保护。', 2, 4, 0, '2026-05-15 18:55:10');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1238, 108, 1234, '人弃我取', '逆向投资，在市场恐慌时买入优质资产。', '逆向是超额收益的来源。', 3, 4, 0, '2026-05-15 18:55:10');
INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1239, 108, 1233, '受托人精神', '强调投资人对客户资金的责任感，宁可丢掉客户也不丢客户的钱。', '理性只会迟到但不会缺席。', 1, 3, 0, '2026-05-15 18:55:10');
