INSERT INTO `study_knowledge_node` (`id`, `course_id`, `parent_id`, `title`, `summary`, `definition`, `sort`, `level`, `mastered`, `created_at`) VALUES (1241, 108, 1239, '长期视角', '投资是长跑，短期波动不代表长期结果。', 'stay in the game是第一规则。', 1, 4, 0, '2026-05-15 18:55:10');
INSERT INTO `study_material` (`id`, `course_id`, `file_name`, `file_type`, `file_path`, `size`, `parse_status`, `progress`, `extracted_text`, `created_at`) VALUES (1, 106, '《投资中最简单的事》.pdf', 'pdf', '/Users/wangmingqiang/Documents/quant-new/gupiao-quant/uploads/660f661c-84c3-42f8-9a15-60ff669076d3_《投资中最简单的事》.pdf', 5541240, 'done', 100, '\n\n\n版权信息\n本书纸版由中国人民大学出版社于 2014年10月出版\n作者授权湛庐文化（Cheers Publishing）作中国大陆（地区）电子版发行（限简体中文）\n版权所有·侵权必究\n书名：投资中最简单的事\n著者：邱国鹭\n字数：167000\n电子书定价：27.99美元\n推荐序\n张磊\n高瓴资本创始人兼董事长\n天下武林，林林总总。名门正宗如少林武当，诚然名扬天下，而武林之大，\n但凡修得暗镖神剑者，亦可独步江湖。所以门派无尊贵，只有适合不适合。本序\n开宗明义：即使最成功的投资人，也要心胸坦荡，认识到自我局限，不可以名门\n正宗自居，须认识到获得真理是一个学无止境、永远追求的过程。\n十八般武艺样样精通，仅出现在武侠传说中。对一个普通理性投资者来说，\n如何走一个心灵宁静（peace of mind）、越走越宽的康庄大道，国鹭这本《投\n资中最简单的事》呈现了一个最直白、最真实、最给力的阐述。\n我对国鹭的景仰，除了他追求真理的真性情以外，便是其极强的自我约束力\n和发自内心的受托人（fiduciary） 责任感。记得看过一个研究报告，发现成功\n与智商等等关系都不大，但与儿时就展现的自我控制力有极大的关系。实验中几\n个小朋友每人分得一个糖果，并被告知如果现在不吃，等到几个小时后大人回\n来，可以拿到更多的糖果。结果有的忍不住，就先吃了眼前的一个，后来再也没\n有糖果吃。而能够忍住眼前诱惑，等到最后的，则得到了几倍的收获。跟踪研究\n发现，那些儿时就展现出自我约束力的小朋友后期成功的可能性大大提高。在多\n数人都醉心于“即时满足”（instant gratification）的世界里，懂得用“延\n迟满足”（delayed gratification）去做交易的人，已先胜一筹了。\n“我宁愿丢掉客户，也不愿丢掉客户的钱。”这种极致的受托人理念不是每\n个投资人都有勇气践行的，但是路遥知马力，坚持下去，必会得到投资人的长期\n支持和信赖。正如国鹭所言，“理性只会迟到，但不会缺席。”\n高瓴资本的成立初衷就是选择一群有意思的人做一些有意思的事。 我们所坚\n持的“守正用奇”在书中得到了最好的印证：坚持价值投资的理念，但同时对主\n流观点保持质疑和求证的精神；清醒地认识到能力圈的边界，但同时不断地挑战\n自我，去开拓新的未知世界。所以我们提出了投资团队的好奇、独立、诚实。在\n热点纷呈的中国一二级资本市场，如果没有定力，不能保持智力上的独立与诚\n实，很难不随波逐流。同时，如果不始终保持和发掘好奇心，很难在这么高强度\n的工作中保持青春与活力。\n“The No.1 rule of the game is to stay in the game”。投资这个\n游戏的第一条规则就是得能够玩下去。再好的投资理念都要放到实践中去验证。\n长期投资、逆向投资最大的敌人是价值陷阱。即使再伟大的投资人，犯错误都是\n必然的。能否把犯错误的代价控制到一定风险范围内，是甄选出一个成熟投资人\n的关键。“君子不立危墙之下。”虽然各种投资方法都有可能产生好的投资回\n报，但其中隐含的风险是大不相同的。大多数情况下，国鹭书中所阐述的价值投\n资和逆向投资理念都是减少风险（derisk）的好方法。\n最后，还是要有个好心境、好家庭、好身体。投资到最后，反映的是你个人\n的真实性情和价值观。健康的环境和心情是长期修行的结果。成功诚然需要运气\n和际遇的配合，但能否幸福地去做投资则掌握在你自己手里。\n如果有机会的话，这本书希望孩子们也来读。\n张磊\n于加州Lake Tahoe, 2014年夏\n自 序\n我投身股市已经22年，进入基金行业担任职业投资人也已经15年了，见证过\n1992年排队买认购证时一本万利的疯狂，经历过1999年纳斯达克鸡犬升天的科技\n股狂潮以及泡沫破裂后狂跌90%的大崩盘，也参与了2008年全球金融危机时对冲基\n金对华尔街投行的挤兑。在市场的风风雨雨中，我时常会有感而发，产生提笔写\n些什么的想法，却总是没能实现。\n三年前开始写微博时，本来只想为自己散乱的投资思考留下只言片语，却意\n外地得到了各方朋友的支持和认可。几篇即兴写就的长微博，居然也都有三四千\n次转发和三四百万次阅读，着实让我惊讶。许多良师益友也一直劝我出本书，把\n近年写下的文章和随笔汇集成册，便于各方朋友阅读和指正。\n这本书起名为《投资中最简单的事》，字面上看是对于霍华德·马克斯的\n《投资最重要的事》的东施效颦之举，但也有背后的深义。投资本身是一件很复\n杂的事，宏观上涉及国家的政治、经济、历史、军事，中观上涉及行业格局演\n变、产业技术进步、上下游产业链变迁，微观上涉及企业的发展战略、公司治\n理、管理层素质、财务状况、产品创新、营销策略等方方面面。我们固然可以通\n过金融学、经济学、心理学、会计学、统计学、社会学、企业管理学等跨学科的\n综合知识体系来应对这个复杂的问题，但是，是否可以化繁为简、直接追问什么\n才是投资的本质？有没有一些简单可行的法则和工具能够让我们直接触及投资的\n本质？既然投资有太多复杂的因素难以把握，我们能不能只试着去把握那些能够\n把握的最简单的事，把那些不能把握的复杂因素留给运气和概率？\n在从业余炒股者成长为职业投资人的过程中，我在不同的阶段钻研过各式各\n样的投资方法：从打探消息、跟庄炒作，到定量投资、程序化交易；从看K线图的\n技术分析，到看财务报表的基本面分析；从精选个股的集中投资，到行业配置的\n组合投资；从寻找未来收入爆发的成长投资，到专注现有资产低估的价值投资。\n这期间我也认识了投资风格各异的成功人士，意识到每个人的性格、经验、学识\n和能力决定了最适合他的投资方式，不论哪种投资方法，只要做到精、做到深、\n做到专，就能立于不败之地。然而，我在实践中也深深地体会到，对于大多数人\n而言，只有价值投资才是真正可学、可用、可掌握的，因此它成为了我职业生涯\n中一直坚持使用的投资方式。\n诚然，对于一个真正的投资者而言，价值和成长是不可割裂的，一个没有成\n长的公司很难说有很高的价值，一个估值过高的成长公司也很难说是好的投资标\n的。但是，如果一定要区分狭义的价值投资和成长投资的话，我会把价值投资表\n述为P0<<V0<Vn，把成长投资表述为P0<V0<<Vn。其中，P0是股票今天的价格，V0\n是公司现在的价值，Vn是公司未来的价值，“<<”代表“远小于”。价值投资和\n成长投资殊途同归，都是希望现在以五毛钱的价格购买未来价值一元钱的企业\n（P0<<Vn），两者的区别无非是企业的价值支撑的来源不同。成长投资的价值支\n撑主要来自企业未来收入和利润的高增长，更强调公司未来的价值Vn要远大于公\n司现在的价值V0，但这种投资需要预测未来的远见，只有极少数的人能够做到。\n价值投资的价值支撑主要来自企业现有资产、利润和现金流，更注重公司现在的\n价格P0是否远小于公司现在的价值V0，这种投资需要分析现在，难度相对较小，\n大多数人通过学习都能够掌握。\n不可否认，每个投资人都有自己的能力边界和局限性，但只要认识到了局限\n性的存在，就可以在一定程度上摆脱它的制约。我对自己的局限性是这样认识\n的：我更擅长总结过去的规律性的东西，而不擅长预测未来的突破和演变；我更\n擅长在变化中寻找不变，而不擅长在不变中寻找变化。意识到这种局限性的存在\n之后，我开始尽力寻找一些历史上被证明行之有效的简单法则、简单工具，然后\n长期坚持。\n比如，我把选股的要素简化为估值、品质和时机，并且淡化了时机的重要性\n（不是因为不重要，而是因为难把握），于是选股的复杂问题就变成了寻找“便\n宜的好公司”这个相对简单的问题。然后，针对不同的行业特性，利用波特五\n力、杜邦分析、估值分析等简单工具，弄清这个行业里决定竞争胜负的关键因素\n是什么、什么样的公司算“好公司”、什么样的价格是“便宜”。举例来说，对\n于餐饮业而言，回头客多、翻台率高、坪效高的就是“好公司”；对于连锁零售\n业而言，同店增长高、开店速度快、应收账款低的就是“好公司”；对于制造业\n而言，规模大、成本低、存货少的就是“好公司”。\n另外，我还努力奉行一些简单的原则，例如：\n第一，便宜才是硬道理。即使是普通公司，只要足够便宜，也会有丰厚的回\n报。A股市场鱼龙混杂，发现“价格合理的伟大公司”的难度远远超过寻找“价格\n被低估的普通公司”。\n第二，定价权是核心竞争力。有核心竞争力的公司有两个标准：一是做的是\n自己可以不断复制的事情，比如麦当劳和星巴克可以不断地跨区域开新店，在全\n世界成功复制；二是做的是别人不可能复制的事情，具备独占资源、品牌美誉\n度、专利、技术、寡头垄断地位、牌照准入限制等特征，最终体现为企业的定价\n权。\n第三，胜而后求战，不要战而后求胜。百舸争流的行业，增长再快也很难找\n投资标的，不妨等待行业“内战”结束、赢家产生后再做投资。许多人担心在胜\n负已分的行业中买赢家会太迟，其实腾讯、百度、格力、茅台等企业在十年前就\n已经是各自行业里的赢家了，但是十年来它们的涨幅依然惊人。\n第四，人弃我取，逆向投资。不论是巴菲特、索罗斯，还是邓普顿、卡尔·\n伊坎，投资领域的集大成者大多数都具有超强的逆向思维能力。A股的情绪波动容\n易走极端，任何概念和主题，无论真假，只要够新够炫，都能在短期内炒翻天，\n但是爆炒之后常是暴跌，因此对于如我这般手脚不快的人来说，“人多的地方不\n去”更是至理名言。\n以上这些都是很简单的法则和工具，所以不可能“总是对”、也不一定“马\n上对”，但是这些法则和工具都是经过许多成功投资人长期验证的、触及投资本\n质的、规律性的东西。这些规律性的东西虽然看起来是投资中最简单的事，却也\n是投资中最本质的东西，并不会因为时空的不同而产生大的差异——虽然每隔几\n年就会有一段时间，市场的狂热让人觉得“这次不同了”。15年来，我亲身经历\n过两次市场对价值投资的广泛质疑，一次是1999年纳斯达克泡沫的顶峰，另一次\n是2013年A股的创业板热潮。虽然两次质疑相隔了14年，但是其中的相似之处如此\n之多，以至于人们不得不感叹人性的亘古不变。虽然科学技术的进步日新月异，\n但是人性中不变的贪婪和恐惧，总能让那些认为“这次不同了”的观点，随着时\n间的推移被证明只不过是对历史的健忘。\n我想把这本书献给我的父亲邱华炳。父亲是位大学教师，一生潜心学术、著\n作等身，学生遍布金融、财税、经济的各个领域。因为父亲，我在成长之初就近\n距离地接触到许多之后的业界精英并向他们学习。不论是在专业还是生活上，父\n亲都是我不折不扣的启蒙老师，他总是教育我做事先做人，要常怀感恩之心，要\n多读书，不在于积累知识而在于培养能力。父亲去世已经十多年了，但是每次遇\n到他以前的学生，许多人依然清晰地记得父亲说过的话和言谈举止的细节，他们\n流露出来的真挚情感和深切怀念，总令我感动不已。本书的稿酬将全部捐给父亲\n生前从事的教育事业和关心的家乡公益事业。\n最后，要特别感谢高瓴资本的张磊先生百忙中为本书作序。张磊先生是我最\n钦佩的投资人，他对行业规律的深刻理解、对企业品质的深入剖析、对格局变化\n的前瞻性把握都是非常值得我学习的地方，他的序言无疑为本书增色许多。同\n时，我也衷心感谢巴曙松、詹余引、陈鸿桥、裘国根和赵丹阳等良师益友们拨冗\n为本书所写的推荐语。韩海峰做了许多协助文字整理的细致工作，在此一并致\n谢。另外，要特别感谢湛庐文化的精心编辑，使原本杂乱无章的众多内容升华成\n一本脉络清晰的书。\n谨以此书与所有的投资人共勉。由于本书由不同时间点所写的文章、随笔和\n演讲实录汇集而成，所作的一些判断和评论都带有鲜明的时间烙印和特定背景，\n请广大读者在阅读时注意甄别。由于作者水平有限，疏漏在所难免，不足之处，\n欢迎各方朋友们批评指正。\n邱国鹭\n2014年7月\n目录\n推荐序\n自 序\n第一部分 投资理念\n01 以实业的眼光做投资\n02 人弃我取，逆向投资的关键\n03 便宜是硬道理\n【投资随想录】\n硬币的两面\n遛狗理论\n个例与规律\n第二部分 投资方法\n04 投资的三个基本问题\n05 宁数月亮，不数星星\n06 经验就像旧衣服\n【投资随想录】\n扑克与投资\n投资眼光\n股票式债券\n第三部分 投资风险\n07 价值陷阱与成长陷阱\n08 真假风险与安全边际\n09 价值投资的局限性\n【投资随想录】\n往事如烟\n几句废话\n第四部分 投资策略\n10 四种周期、三种杠杆，行业轮动时机的把握\n11 未来10年：投资路在何方\n12 对冲中国：机遇与挑战\n【投资随想录】\n投资大白话\n国家竞争优势\n《美国士兵守则》的投资解读\n第五部分 投资心理学 投资心理学\n13 人性的弱点：投资者常见的心理误区\n14 后视镜\n15 傻瓜定价说\n16 这次不同了\n17 树动风动心动\n18 知易行难\n附录 投资访谈 投资访谈\n投资需要逆向思维\nA股市场是价值投资者的乐土\n“超额收益主要来自行业配置，国内啤酒业已至拐点”\n“狼性3号”：一种是跑得快的人，另一种是熬得住的人\n投资戒盲目，慎选“风口的猪”\n后 记\n\n\n\n\n\n听邱国鹭谈行业投资\n#护城河#\n每三四年就得重挖一次的护城河其实不能算是护城河，而没有护城河就不断会有前浪死在沙\n滩上。在一个先发优势不断被颠覆、没有永远的赢家的行业里，只有勇于自我否定、因时而\n变才能生存。\n#成长vs门槛#\n多数人喜欢成长，但我喜欢门槛。成长是未来的，难预测；门槛是既成的，易把握。高门槛\n行业，新进入者难存活，因此行业供给受限，竞争有序，有利于企业盈利增长。低门槛行\n业，行业供给增长快，无序竞争，谁也赚不到钱。（门槛，即行业护城河）\n#成长vs门槛：案例#\n白色家电行业2000—2005年增长迅速，但利润不佳，股价疲软；2006—2010年行业增速减\n缓，但利润大增，龙头股价上涨十几倍。拐点是2005年行业大洗牌，小厂退出，之后龙头企\n业在规模、渠道、成本、品牌等方面优势扩大，阻止了新进入者，行业格局从野蛮生长的无\n序竞争转变为有门槛的有序竞争。\n十几年前我刚进入基金业的时候，曾问过公司的一位资深合伙人，怎样才能\n成为一名优秀的基金经理。他说，其实很简单，你只要记住两条：第一，把客户\n的钱当作自己的钱来珍惜；第二，把二级市场的股票投资当作一级市场的实业投\n资来分析。\n这是不是一门好生意\n如果用自己的钱做实业投资，首先要考虑的问题就是：这是不是一门好生\n意。不过，二级市场有时就是偏爱“烂生意”。比如2013年市场上非常火爆的手\n机游戏行业，就是一门烂生意。\n根据艾瑞咨询的不完全统计，2012年仅在苹果的IOS平台上，就有3 883家公\n司推出的10 400款手机游戏，如果再加上安卓平台就更是不计其数了。但在这么\n多的游戏当中，月流水过千万的却屈指可数。\n即使你行大运做出了一款火爆的游戏，产品的生命周期一般也只有3~6个月，\n之后你就得推出新产品。而事实上，在数千家游戏开发商中，能够连续推出两款\n火爆游戏的实在是凤毛麟角。目前绝大多数的手机游戏是单机游戏，单机游戏的\n特点就是产品生命短，这一点和网页游戏很像。事实表明，页游行业的内容开发\n方很难做大，只是市场选择对此视而不见罢了。\n手游不像端游那样有较好的用户黏度，一款重度端游可以火个五年十年，靠\n的是在游戏中建立起的一种深度互动的、牢固的社会关系。但是，社交游戏也不\n能保证自身的持续性，就像Facebook上曾经一统江湖的Zynga，过去这一年多股\n价暴跌80%。几年前，火得不能再火的偷瓜偷菜游戏也是熟人之间的社交游戏，但\n是火过一阵子也就销声匿迹了，这样的商业模式你怎么能给出高估值呢？他今年\n赚的钱再多，你怎么能够知道三五年后这家公司是否还能像现在一样红火呢？而\n且，手机游戏内容开发商的议价权其实是很有限的，主要的钱都被平台商赚走\n了。\n大家都想成为平台，但是，要成为一个平台又谈何容易？苹果系统只有一个\n平台，安卓平台最后成功的可能也只有两三个，再加上腾讯的微信平台，铁定又\n要分流走很多游戏玩家。在这样的形势下，手机游戏开发商其实只能是“人为刀\n俎，我为鱼肉”，让平台把百分之七八十的收入分走。\n人们只看到7亿手机用户这个巨大的市场，却忽视了这其实是个竞争无比激\n烈、一将功成万骨枯的行业。人们只看到成功的“一将”，选择性地忽视了“枯\n了的万骨”。任何公司只要跟手游沾点边就能够被爆炒，甚至连旅游公司推出个\n手机自助游软件也能够受到市场的追捧。市场的非理性可见一斑。\n投资微论\n长期牛股 什么行业易出长期牛股？行业集中度持续提高的行业。因为这\n样的行业有门槛，有先发优势，后浪没法让前浪死在沙滩上，易出大牛股。\n相反，如果行业越来越分散，说明行业门槛不高，既有的领先者没有足够深\n的护城河来阻止追赶者抢夺其市场份额，这种行业一般是城头变幻大王旗，\n各领风骚两三年。\n企业的商业模式和现金流状况\n用自己的钱做实业投资要考虑的第二个问题，就是这门生意的现金流状况如\n何，毕竟做生意的最终目的是赚取现金流。\n2013年受市场热捧的电影行业其实是个现金流状况很差的行业。中国每年会\n拍七百多部电影，只有两百多部能够上映，其中票房能够超过五亿的屈指可数。\n即使赚了五亿的票房“大获成功”的电影，扣除分给院线的一半，再扣除发行费\n宣传费，制片方能够拿到手的大概只有2亿多一点。再扣除给编剧、导演、制片和\n演员的薪酬以及拍摄中的各种成本，最后剩下的净利润可能只有几千万。\n更麻烦的是，从现金流的角度看，拍电影得先写剧本，然后请导演、搭班\n子、雇演员，支出一大笔费用，一年半载之后影片开始发行、宣传，又是一大笔\n费用，而且电影公映之后要等好几个月才能从票房中分到钱。所以很多电影公司\n不管利润怎样，现金流都是大幅为负，抗风险能力特别弱，一有风吹草动就容易\n元气大伤。\n不论是美国的百年老店米高梅，还是后起之秀梦工厂，只要有一片大制作成\n了票房毒药，就逃脱不了破产和被收购的命运。美国的电影业发展了上百年，居\n然没有一家独立的电影公司，全都只是大型的综合传媒集团的一部分，这也体现\n了电影作为一个独立的商业模式的内在缺陷。\n另外，电影的定价权掌握在导演和演员手里，观众买票到电影院是去看范冰\n冰、徐峥和冯小刚的，不是去看电影公司的，所以名导演和名演员的薪酬总能涨\n到让电影制片方不怎么赚钱的水平。就好比欧洲的足坛，虽然球星拥有天价收\n入，俱乐部却在亏损，原因很简单：定价权在球星手里。迪士尼能够历经百年屹\n立不倒，很重要的原因是米老鼠和唐老鸭不会要求涨片酬。\n用自己的钱做实业投资的人，除了些另有所图的暴发户以外，很少有人会真\n金白银地砸重金投资电影，因为这是个现金流很差、不确定性很高的行业。A股的\n电影公司动辄两三百亿市值，但是与他们相同体量的在美股上市的中国电影公司\n的市值却只有15亿人民币，两者相差十几倍。\n我们再来比较一下房地产公司的商业模式，北上广深随便卖栋别墅都是几千\n万利润，顶得上一部好电影了。拍电影不一定每部都能火，而别墅几乎每栋都卖\n得掉。再从现金流的角度看，地产公司只要出钱拍了地，挖个坑、做个沙盘就可\n以预售了，客户会排着队把钱交上，他用你的钱盖你的房子，自己对现金流的要\n求其实并不高（盲目高价拿地的除外）。\n投资微论\n好公司的两个标准 一是它做的事情别人做不了；二是它做的事情自己可\n以重复做。前者是门槛，决定利润率的高低和趋势；后者是成长的可复制\n性，决定销售增速。如果二者不可兼得，宁要有门槛的低增长（可持续），\n也不要没门槛的高增长（不可持续）。门槛是现有的，好把握；成长是将来\n的，难预测。\n行业的竞争格', '2026-05-15 18:35:47');
INSERT INTO `study_material` (`id`, `course_id`, `file_name`, `file_type`, `file_path`, `size`, `parse_status`, `progress`, `extracted_text`, `created_at`) VALUES (2, 107, '《投资中最简单的事》.pdf', 'pdf', '/Users/wangmingqiang/Documents/quant-new/gupiao-quant/uploads/fe3f6d95-5829-4f77-9fdb-d7941923d0f3_《投资中最简单的事》.pdf', 5541240, 'done', 100, '\n\n\n版权信息\n本书纸版由中国人民大学出版社于 2014年10月出版\n作者授权湛庐文化（Cheers Publishing）作中国大陆（地区）电子版发行（限简体中文）\n版权所有·侵权必究\n书名：投资中最简单的事\n著者：邱国鹭\n字数：167000\n电子书定价：27.99美元\n推荐序\n张磊\n高瓴资本创始人兼董事长\n天下武林，林林总总。名门正宗如少林武当，诚然名扬天下，而武林之大，\n但凡修得暗镖神剑者，亦可独步江湖。所以门派无尊贵，只有适合不适合。本序\n开宗明义：即使最成功的投资人，也要心胸坦荡，认识到自我局限，不可以名门\n正宗自居，须认识到获得真理是一个学无止境、永远追求的过程。\n十八般武艺样样精通，仅出现在武侠传说中。对一个普通理性投资者来说，\n如何走一个心灵宁静（peace of mind）、越走越宽的康庄大道，国鹭这本《投\n资中最简单的事》呈现了一个最直白、最真实、最给力的阐述。\n我对国鹭的景仰，除了他追求真理的真性情以外，便是其极强的自我约束力\n和发自内心的受托人（fiduciary） 责任感。记得看过一个研究报告，发现成功\n与智商等等关系都不大，但与儿时就展现的自我控制力有极大的关系。实验中几\n个小朋友每人分得一个糖果，并被告知如果现在不吃，等到几个小时后大人回\n来，可以拿到更多的糖果。结果有的忍不住，就先吃了眼前的一个，后来再也没\n有糖果吃。而能够忍住眼前诱惑，等到最后的，则得到了几倍的收获。跟踪研究\n发现，那些儿时就展现出自我约束力的小朋友后期成功的可能性大大提高。在多\n数人都醉心于“即时满足”（instant gratification）的世界里，懂得用“延\n迟满足”（delayed gratification）去做交易的人，已先胜一筹了。\n“我宁愿丢掉客户，也不愿丢掉客户的钱。”这种极致的受托人理念不是每\n个投资人都有勇气践行的，但是路遥知马力，坚持下去，必会得到投资人的长期\n支持和信赖。正如国鹭所言，“理性只会迟到，但不会缺席。”\n高瓴资本的成立初衷就是选择一群有意思的人做一些有意思的事。 我们所坚\n持的“守正用奇”在书中得到了最好的印证：坚持价值投资的理念，但同时对主\n流观点保持质疑和求证的精神；清醒地认识到能力圈的边界，但同时不断地挑战\n自我，去开拓新的未知世界。所以我们提出了投资团队的好奇、独立、诚实。在\n热点纷呈的中国一二级资本市场，如果没有定力，不能保持智力上的独立与诚\n实，很难不随波逐流。同时，如果不始终保持和发掘好奇心，很难在这么高强度\n的工作中保持青春与活力。\n“The No.1 rule of the game is to stay in the game”。投资这个\n游戏的第一条规则就是得能够玩下去。再好的投资理念都要放到实践中去验证。\n长期投资、逆向投资最大的敌人是价值陷阱。即使再伟大的投资人，犯错误都是\n必然的。能否把犯错误的代价控制到一定风险范围内，是甄选出一个成熟投资人\n的关键。“君子不立危墙之下。”虽然各种投资方法都有可能产生好的投资回\n报，但其中隐含的风险是大不相同的。大多数情况下，国鹭书中所阐述的价值投\n资和逆向投资理念都是减少风险（derisk）的好方法。\n最后，还是要有个好心境、好家庭、好身体。投资到最后，反映的是你个人\n的真实性情和价值观。健康的环境和心情是长期修行的结果。成功诚然需要运气\n和际遇的配合，但能否幸福地去做投资则掌握在你自己手里。\n如果有机会的话，这本书希望孩子们也来读。\n张磊\n于加州Lake Tahoe, 2014年夏\n自 序\n我投身股市已经22年，进入基金行业担任职业投资人也已经15年了，见证过\n1992年排队买认购证时一本万利的疯狂，经历过1999年纳斯达克鸡犬升天的科技\n股狂潮以及泡沫破裂后狂跌90%的大崩盘，也参与了2008年全球金融危机时对冲基\n金对华尔街投行的挤兑。在市场的风风雨雨中，我时常会有感而发，产生提笔写\n些什么的想法，却总是没能实现。\n三年前开始写微博时，本来只想为自己散乱的投资思考留下只言片语，却意\n外地得到了各方朋友的支持和认可。几篇即兴写就的长微博，居然也都有三四千\n次转发和三四百万次阅读，着实让我惊讶。许多良师益友也一直劝我出本书，把\n近年写下的文章和随笔汇集成册，便于各方朋友阅读和指正。\n这本书起名为《投资中最简单的事》，字面上看是对于霍华德·马克斯的\n《投资最重要的事》的东施效颦之举，但也有背后的深义。投资本身是一件很复\n杂的事，宏观上涉及国家的政治、经济、历史、军事，中观上涉及行业格局演\n变、产业技术进步、上下游产业链变迁，微观上涉及企业的发展战略、公司治\n理、管理层素质、财务状况、产品创新、营销策略等方方面面。我们固然可以通\n过金融学、经济学、心理学、会计学、统计学、社会学、企业管理学等跨学科的\n综合知识体系来应对这个复杂的问题，但是，是否可以化繁为简、直接追问什么\n才是投资的本质？有没有一些简单可行的法则和工具能够让我们直接触及投资的\n本质？既然投资有太多复杂的因素难以把握，我们能不能只试着去把握那些能够\n把握的最简单的事，把那些不能把握的复杂因素留给运气和概率？\n在从业余炒股者成长为职业投资人的过程中，我在不同的阶段钻研过各式各\n样的投资方法：从打探消息、跟庄炒作，到定量投资、程序化交易；从看K线图的\n技术分析，到看财务报表的基本面分析；从精选个股的集中投资，到行业配置的\n组合投资；从寻找未来收入爆发的成长投资，到专注现有资产低估的价值投资。\n这期间我也认识了投资风格各异的成功人士，意识到每个人的性格、经验、学识\n和能力决定了最适合他的投资方式，不论哪种投资方法，只要做到精、做到深、\n做到专，就能立于不败之地。然而，我在实践中也深深地体会到，对于大多数人\n而言，只有价值投资才是真正可学、可用、可掌握的，因此它成为了我职业生涯\n中一直坚持使用的投资方式。\n诚然，对于一个真正的投资者而言，价值和成长是不可割裂的，一个没有成\n长的公司很难说有很高的价值，一个估值过高的成长公司也很难说是好的投资标\n的。但是，如果一定要区分狭义的价值投资和成长投资的话，我会把价值投资表\n述为P0<<V0<Vn，把成长投资表述为P0<V0<<Vn。其中，P0是股票今天的价格，V0\n是公司现在的价值，Vn是公司未来的价值，“<<”代表“远小于”。价值投资和\n成长投资殊途同归，都是希望现在以五毛钱的价格购买未来价值一元钱的企业\n（P0<<Vn），两者的区别无非是企业的价值支撑的来源不同。成长投资的价值支\n撑主要来自企业未来收入和利润的高增长，更强调公司未来的价值Vn要远大于公\n司现在的价值V0，但这种投资需要预测未来的远见，只有极少数的人能够做到。\n价值投资的价值支撑主要来自企业现有资产、利润和现金流，更注重公司现在的\n价格P0是否远小于公司现在的价值V0，这种投资需要分析现在，难度相对较小，\n大多数人通过学习都能够掌握。\n不可否认，每个投资人都有自己的能力边界和局限性，但只要认识到了局限\n性的存在，就可以在一定程度上摆脱它的制约。我对自己的局限性是这样认识\n的：我更擅长总结过去的规律性的东西，而不擅长预测未来的突破和演变；我更\n擅长在变化中寻找不变，而不擅长在不变中寻找变化。意识到这种局限性的存在\n之后，我开始尽力寻找一些历史上被证明行之有效的简单法则、简单工具，然后\n长期坚持。\n比如，我把选股的要素简化为估值、品质和时机，并且淡化了时机的重要性\n（不是因为不重要，而是因为难把握），于是选股的复杂问题就变成了寻找“便\n宜的好公司”这个相对简单的问题。然后，针对不同的行业特性，利用波特五\n力、杜邦分析、估值分析等简单工具，弄清这个行业里决定竞争胜负的关键因素\n是什么、什么样的公司算“好公司”、什么样的价格是“便宜”。举例来说，对\n于餐饮业而言，回头客多、翻台率高、坪效高的就是“好公司”；对于连锁零售\n业而言，同店增长高、开店速度快、应收账款低的就是“好公司”；对于制造业\n而言，规模大、成本低、存货少的就是“好公司”。\n另外，我还努力奉行一些简单的原则，例如：\n第一，便宜才是硬道理。即使是普通公司，只要足够便宜，也会有丰厚的回\n报。A股市场鱼龙混杂，发现“价格合理的伟大公司”的难度远远超过寻找“价格\n被低估的普通公司”。\n第二，定价权是核心竞争力。有核心竞争力的公司有两个标准：一是做的是\n自己可以不断复制的事情，比如麦当劳和星巴克可以不断地跨区域开新店，在全\n世界成功复制；二是做的是别人不可能复制的事情，具备独占资源、品牌美誉\n度、专利、技术、寡头垄断地位、牌照准入限制等特征，最终体现为企业的定价\n权。\n第三，胜而后求战，不要战而后求胜。百舸争流的行业，增长再快也很难找\n投资标的，不妨等待行业“内战”结束、赢家产生后再做投资。许多人担心在胜\n负已分的行业中买赢家会太迟，其实腾讯、百度、格力、茅台等企业在十年前就\n已经是各自行业里的赢家了，但是十年来它们的涨幅依然惊人。\n第四，人弃我取，逆向投资。不论是巴菲特、索罗斯，还是邓普顿、卡尔·\n伊坎，投资领域的集大成者大多数都具有超强的逆向思维能力。A股的情绪波动容\n易走极端，任何概念和主题，无论真假，只要够新够炫，都能在短期内炒翻天，\n但是爆炒之后常是暴跌，因此对于如我这般手脚不快的人来说，“人多的地方不\n去”更是至理名言。\n以上这些都是很简单的法则和工具，所以不可能“总是对”、也不一定“马\n上对”，但是这些法则和工具都是经过许多成功投资人长期验证的、触及投资本\n质的、规律性的东西。这些规律性的东西虽然看起来是投资中最简单的事，却也\n是投资中最本质的东西，并不会因为时空的不同而产生大的差异——虽然每隔几\n年就会有一段时间，市场的狂热让人觉得“这次不同了”。15年来，我亲身经历\n过两次市场对价值投资的广泛质疑，一次是1999年纳斯达克泡沫的顶峰，另一次\n是2013年A股的创业板热潮。虽然两次质疑相隔了14年，但是其中的相似之处如此\n之多，以至于人们不得不感叹人性的亘古不变。虽然科学技术的进步日新月异，\n但是人性中不变的贪婪和恐惧，总能让那些认为“这次不同了”的观点，随着时\n间的推移被证明只不过是对历史的健忘。\n我想把这本书献给我的父亲邱华炳。父亲是位大学教师，一生潜心学术、著\n作等身，学生遍布金融、财税、经济的各个领域。因为父亲，我在成长之初就近\n距离地接触到许多之后的业界精英并向他们学习。不论是在专业还是生活上，父\n亲都是我不折不扣的启蒙老师，他总是教育我做事先做人，要常怀感恩之心，要\n多读书，不在于积累知识而在于培养能力。父亲去世已经十多年了，但是每次遇\n到他以前的学生，许多人依然清晰地记得父亲说过的话和言谈举止的细节，他们\n流露出来的真挚情感和深切怀念，总令我感动不已。本书的稿酬将全部捐给父亲\n生前从事的教育事业和关心的家乡公益事业。\n最后，要特别感谢高瓴资本的张磊先生百忙中为本书作序。张磊先生是我最\n钦佩的投资人，他对行业规律的深刻理解、对企业品质的深入剖析、对格局变化\n的前瞻性把握都是非常值得我学习的地方，他的序言无疑为本书增色许多。同\n时，我也衷心感谢巴曙松、詹余引、陈鸿桥、裘国根和赵丹阳等良师益友们拨冗\n为本书所写的推荐语。韩海峰做了许多协助文字整理的细致工作，在此一并致\n谢。另外，要特别感谢湛庐文化的精心编辑，使原本杂乱无章的众多内容升华成\n一本脉络清晰的书。\n谨以此书与所有的投资人共勉。由于本书由不同时间点所写的文章、随笔和\n演讲实录汇集而成，所作的一些判断和评论都带有鲜明的时间烙印和特定背景，\n请广大读者在阅读时注意甄别。由于作者水平有限，疏漏在所难免，不足之处，\n欢迎各方朋友们批评指正。\n邱国鹭\n2014年7月\n目录\n推荐序\n自 序\n第一部分 投资理念\n01 以实业的眼光做投资\n02 人弃我取，逆向投资的关键\n03 便宜是硬道理\n【投资随想录】\n硬币的两面\n遛狗理论\n个例与规律\n第二部分 投资方法\n04 投资的三个基本问题\n05 宁数月亮，不数星星\n06 经验就像旧衣服\n【投资随想录】\n扑克与投资\n投资眼光\n股票式债券\n第三部分 投资风险\n07 价值陷阱与成长陷阱\n08 真假风险与安全边际\n09 价值投资的局限性\n【投资随想录】\n往事如烟\n几句废话\n第四部分 投资策略\n10 四种周期、三种杠杆，行业轮动时机的把握\n11 未来10年：投资路在何方\n12 对冲中国：机遇与挑战\n【投资随想录】\n投资大白话\n国家竞争优势\n《美国士兵守则》的投资解读\n第五部分 投资心理学 投资心理学\n13 人性的弱点：投资者常见的心理误区\n14 后视镜\n15 傻瓜定价说\n16 这次不同了\n17 树动风动心动\n18 知易行难\n附录 投资访谈 投资访谈\n投资需要逆向思维\nA股市场是价值投资者的乐土\n“超额收益主要来自行业配置，国内啤酒业已至拐点”\n“狼性3号”：一种是跑得快的人，另一种是熬得住的人\n投资戒盲目，慎选“风口的猪”\n后 记\n\n\n\n\n\n听邱国鹭谈行业投资\n#护城河#\n每三四年就得重挖一次的护城河其实不能算是护城河，而没有护城河就不断会有前浪死在沙\n滩上。在一个先发优势不断被颠覆、没有永远的赢家的行业里，只有勇于自我否定、因时而\n变才能生存。\n#成长vs门槛#\n多数人喜欢成长，但我喜欢门槛。成长是未来的，难预测；门槛是既成的，易把握。高门槛\n行业，新进入者难存活，因此行业供给受限，竞争有序，有利于企业盈利增长。低门槛行\n业，行业供给增长快，无序竞争，谁也赚不到钱。（门槛，即行业护城河）\n#成长vs门槛：案例#\n白色家电行业2000—2005年增长迅速，但利润不佳，股价疲软；2006—2010年行业增速减\n缓，但利润大增，龙头股价上涨十几倍。拐点是2005年行业大洗牌，小厂退出，之后龙头企\n业在规模、渠道、成本、品牌等方面优势扩大，阻止了新进入者，行业格局从野蛮生长的无\n序竞争转变为有门槛的有序竞争。\n十几年前我刚进入基金业的时候，曾问过公司的一位资深合伙人，怎样才能\n成为一名优秀的基金经理。他说，其实很简单，你只要记住两条：第一，把客户\n的钱当作自己的钱来珍惜；第二，把二级市场的股票投资当作一级市场的实业投\n资来分析。\n这是不是一门好生意\n如果用自己的钱做实业投资，首先要考虑的问题就是：这是不是一门好生\n意。不过，二级市场有时就是偏爱“烂生意”。比如2013年市场上非常火爆的手\n机游戏行业，就是一门烂生意。\n根据艾瑞咨询的不完全统计，2012年仅在苹果的IOS平台上，就有3 883家公\n司推出的10 400款手机游戏，如果再加上安卓平台就更是不计其数了。但在这么\n多的游戏当中，月流水过千万的却屈指可数。\n即使你行大运做出了一款火爆的游戏，产品的生命周期一般也只有3~6个月，\n之后你就得推出新产品。而事实上，在数千家游戏开发商中，能够连续推出两款\n火爆游戏的实在是凤毛麟角。目前绝大多数的手机游戏是单机游戏，单机游戏的\n特点就是产品生命短，这一点和网页游戏很像。事实表明，页游行业的内容开发\n方很难做大，只是市场选择对此视而不见罢了。\n手游不像端游那样有较好的用户黏度，一款重度端游可以火个五年十年，靠\n的是在游戏中建立起的一种深度互动的、牢固的社会关系。但是，社交游戏也不\n能保证自身的持续性，就像Facebook上曾经一统江湖的Zynga，过去这一年多股\n价暴跌80%。几年前，火得不能再火的偷瓜偷菜游戏也是熟人之间的社交游戏，但\n是火过一阵子也就销声匿迹了，这样的商业模式你怎么能给出高估值呢？他今年\n赚的钱再多，你怎么能够知道三五年后这家公司是否还能像现在一样红火呢？而\n且，手机游戏内容开发商的议价权其实是很有限的，主要的钱都被平台商赚走\n了。\n大家都想成为平台，但是，要成为一个平台又谈何容易？苹果系统只有一个\n平台，安卓平台最后成功的可能也只有两三个，再加上腾讯的微信平台，铁定又\n要分流走很多游戏玩家。在这样的形势下，手机游戏开发商其实只能是“人为刀\n俎，我为鱼肉”，让平台把百分之七八十的收入分走。\n人们只看到7亿手机用户这个巨大的市场，却忽视了这其实是个竞争无比激\n烈、一将功成万骨枯的行业。人们只看到成功的“一将”，选择性地忽视了“枯\n了的万骨”。任何公司只要跟手游沾点边就能够被爆炒，甚至连旅游公司推出个\n手机自助游软件也能够受到市场的追捧。市场的非理性可见一斑。\n投资微论\n长期牛股 什么行业易出长期牛股？行业集中度持续提高的行业。因为这\n样的行业有门槛，有先发优势，后浪没法让前浪死在沙滩上，易出大牛股。\n相反，如果行业越来越分散，说明行业门槛不高，既有的领先者没有足够深\n的护城河来阻止追赶者抢夺其市场份额，这种行业一般是城头变幻大王旗，\n各领风骚两三年。\n企业的商业模式和现金流状况\n用自己的钱做实业投资要考虑的第二个问题，就是这门生意的现金流状况如\n何，毕竟做生意的最终目的是赚取现金流。\n2013年受市场热捧的电影行业其实是个现金流状况很差的行业。中国每年会\n拍七百多部电影，只有两百多部能够上映，其中票房能够超过五亿的屈指可数。\n即使赚了五亿的票房“大获成功”的电影，扣除分给院线的一半，再扣除发行费\n宣传费，制片方能够拿到手的大概只有2亿多一点。再扣除给编剧、导演、制片和\n演员的薪酬以及拍摄中的各种成本，最后剩下的净利润可能只有几千万。\n更麻烦的是，从现金流的角度看，拍电影得先写剧本，然后请导演、搭班\n子、雇演员，支出一大笔费用，一年半载之后影片开始发行、宣传，又是一大笔\n费用，而且电影公映之后要等好几个月才能从票房中分到钱。所以很多电影公司\n不管利润怎样，现金流都是大幅为负，抗风险能力特别弱，一有风吹草动就容易\n元气大伤。\n不论是美国的百年老店米高梅，还是后起之秀梦工厂，只要有一片大制作成\n了票房毒药，就逃脱不了破产和被收购的命运。美国的电影业发展了上百年，居\n然没有一家独立的电影公司，全都只是大型的综合传媒集团的一部分，这也体现\n了电影作为一个独立的商业模式的内在缺陷。\n另外，电影的定价权掌握在导演和演员手里，观众买票到电影院是去看范冰\n冰、徐峥和冯小刚的，不是去看电影公司的，所以名导演和名演员的薪酬总能涨\n到让电影制片方不怎么赚钱的水平。就好比欧洲的足坛，虽然球星拥有天价收\n入，俱乐部却在亏损，原因很简单：定价权在球星手里。迪士尼能够历经百年屹\n立不倒，很重要的原因是米老鼠和唐老鸭不会要求涨片酬。\n用自己的钱做实业投资的人，除了些另有所图的暴发户以外，很少有人会真\n金白银地砸重金投资电影，因为这是个现金流很差、不确定性很高的行业。A股的\n电影公司动辄两三百亿市值，但是与他们相同体量的在美股上市的中国电影公司\n的市值却只有15亿人民币，两者相差十几倍。\n我们再来比较一下房地产公司的商业模式，北上广深随便卖栋别墅都是几千\n万利润，顶得上一部好电影了。拍电影不一定每部都能火，而别墅几乎每栋都卖\n得掉。再从现金流的角度看，地产公司只要出钱拍了地，挖个坑、做个沙盘就可\n以预售了，客户会排着队把钱交上，他用你的钱盖你的房子，自己对现金流的要\n求其实并不高（盲目高价拿地的除外）。\n投资微论\n好公司的两个标准 一是它做的事情别人做不了；二是它做的事情自己可\n以重复做。前者是门槛，决定利润率的高低和趋势；后者是成长的可复制\n性，决定销售增速。如果二者不可兼得，宁要有门槛的低增长（可持续），\n也不要没门槛的高增长（不可持续）。门槛是现有的，好把握；成长是将来\n的，难预测。\n行业的竞争格', '2026-05-15 18:47:52');
INSERT INTO `study_material` (`id`, `course_id`, `file_name`, `file_type`, `file_path`, `size`, `parse_status`, `progress`, `extracted_text`, `created_at`) VALUES (3, 108, '《投资中最简单的事》.pdf', 'pdf', '/Users/wangmingqiang/Documents/quant-new/gupiao-quant/uploads/5479e381-4359-446c-811e-6160544e9709_《投资中最简单的事》.pdf', 5541240, 'done', 100, '\n\n\n版权信息\n本书纸版由中国人民大学出版社于 2014年10月出版\n作者授权湛庐文化（Cheers Publishing）作中国大陆（地区）电子版发行（限简体中文）\n版权所有·侵权必究\n书名：投资中最简单的事\n著者：邱国鹭\n字数：167000\n电子书定价：27.99美元\n推荐序\n张磊\n高瓴资本创始人兼董事长\n天下武林，林林总总。名门正宗如少林武当，诚然名扬天下，而武林之大，\n但凡修得暗镖神剑者，亦可独步江湖。所以门派无尊贵，只有适合不适合。本序\n开宗明义：即使最成功的投资人，也要心胸坦荡，认识到自我局限，不可以名门\n正宗自居，须认识到获得真理是一个学无止境、永远追求的过程。\n十八般武艺样样精通，仅出现在武侠传说中。对一个普通理性投资者来说，\n如何走一个心灵宁静（peace of mind）、越走越宽的康庄大道，国鹭这本《投\n资中最简单的事》呈现了一个最直白、最真实、最给力的阐述。\n我对国鹭的景仰，除了他追求真理的真性情以外，便是其极强的自我约束力\n和发自内心的受托人（fiduciary） 责任感。记得看过一个研究报告，发现成功\n与智商等等关系都不大，但与儿时就展现的自我控制力有极大的关系。实验中几\n个小朋友每人分得一个糖果，并被告知如果现在不吃，等到几个小时后大人回\n来，可以拿到更多的糖果。结果有的忍不住，就先吃了眼前的一个，后来再也没\n有糖果吃。而能够忍住眼前诱惑，等到最后的，则得到了几倍的收获。跟踪研究\n发现，那些儿时就展现出自我约束力的小朋友后期成功的可能性大大提高。在多\n数人都醉心于“即时满足”（instant gratification）的世界里，懂得用“延\n迟满足”（delayed gratification）去做交易的人，已先胜一筹了。\n“我宁愿丢掉客户，也不愿丢掉客户的钱。”这种极致的受托人理念不是每\n个投资人都有勇气践行的，但是路遥知马力，坚持下去，必会得到投资人的长期\n支持和信赖。正如国鹭所言，“理性只会迟到，但不会缺席。”\n高瓴资本的成立初衷就是选择一群有意思的人做一些有意思的事。 我们所坚\n持的“守正用奇”在书中得到了最好的印证：坚持价值投资的理念，但同时对主\n流观点保持质疑和求证的精神；清醒地认识到能力圈的边界，但同时不断地挑战\n自我，去开拓新的未知世界。所以我们提出了投资团队的好奇、独立、诚实。在\n热点纷呈的中国一二级资本市场，如果没有定力，不能保持智力上的独立与诚\n实，很难不随波逐流。同时，如果不始终保持和发掘好奇心，很难在这么高强度\n的工作中保持青春与活力。\n“The No.1 rule of the game is to stay in the game”。投资这个\n游戏的第一条规则就是得能够玩下去。再好的投资理念都要放到实践中去验证。\n长期投资、逆向投资最大的敌人是价值陷阱。即使再伟大的投资人，犯错误都是\n必然的。能否把犯错误的代价控制到一定风险范围内，是甄选出一个成熟投资人\n的关键。“君子不立危墙之下。”虽然各种投资方法都有可能产生好的投资回\n报，但其中隐含的风险是大不相同的。大多数情况下，国鹭书中所阐述的价值投\n资和逆向投资理念都是减少风险（derisk）的好方法。\n最后，还是要有个好心境、好家庭、好身体。投资到最后，反映的是你个人\n的真实性情和价值观。健康的环境和心情是长期修行的结果。成功诚然需要运气\n和际遇的配合，但能否幸福地去做投资则掌握在你自己手里。\n如果有机会的话，这本书希望孩子们也来读。\n张磊\n于加州Lake Tahoe, 2014年夏\n自 序\n我投身股市已经22年，进入基金行业担任职业投资人也已经15年了，见证过\n1992年排队买认购证时一本万利的疯狂，经历过1999年纳斯达克鸡犬升天的科技\n股狂潮以及泡沫破裂后狂跌90%的大崩盘，也参与了2008年全球金融危机时对冲基\n金对华尔街投行的挤兑。在市场的风风雨雨中，我时常会有感而发，产生提笔写\n些什么的想法，却总是没能实现。\n三年前开始写微博时，本来只想为自己散乱的投资思考留下只言片语，却意\n外地得到了各方朋友的支持和认可。几篇即兴写就的长微博，居然也都有三四千\n次转发和三四百万次阅读，着实让我惊讶。许多良师益友也一直劝我出本书，把\n近年写下的文章和随笔汇集成册，便于各方朋友阅读和指正。\n这本书起名为《投资中最简单的事》，字面上看是对于霍华德·马克斯的\n《投资最重要的事》的东施效颦之举，但也有背后的深义。投资本身是一件很复\n杂的事，宏观上涉及国家的政治、经济、历史、军事，中观上涉及行业格局演\n变、产业技术进步、上下游产业链变迁，微观上涉及企业的发展战略、公司治\n理、管理层素质、财务状况、产品创新、营销策略等方方面面。我们固然可以通\n过金融学、经济学、心理学、会计学、统计学、社会学、企业管理学等跨学科的\n综合知识体系来应对这个复杂的问题，但是，是否可以化繁为简、直接追问什么\n才是投资的本质？有没有一些简单可行的法则和工具能够让我们直接触及投资的\n本质？既然投资有太多复杂的因素难以把握，我们能不能只试着去把握那些能够\n把握的最简单的事，把那些不能把握的复杂因素留给运气和概率？\n在从业余炒股者成长为职业投资人的过程中，我在不同的阶段钻研过各式各\n样的投资方法：从打探消息、跟庄炒作，到定量投资、程序化交易；从看K线图的\n技术分析，到看财务报表的基本面分析；从精选个股的集中投资，到行业配置的\n组合投资；从寻找未来收入爆发的成长投资，到专注现有资产低估的价值投资。\n这期间我也认识了投资风格各异的成功人士，意识到每个人的性格、经验、学识\n和能力决定了最适合他的投资方式，不论哪种投资方法，只要做到精、做到深、\n做到专，就能立于不败之地。然而，我在实践中也深深地体会到，对于大多数人\n而言，只有价值投资才是真正可学、可用、可掌握的，因此它成为了我职业生涯\n中一直坚持使用的投资方式。\n诚然，对于一个真正的投资者而言，价值和成长是不可割裂的，一个没有成\n长的公司很难说有很高的价值，一个估值过高的成长公司也很难说是好的投资标\n的。但是，如果一定要区分狭义的价值投资和成长投资的话，我会把价值投资表\n述为P0<<V0<Vn，把成长投资表述为P0<V0<<Vn。其中，P0是股票今天的价格，V0\n是公司现在的价值，Vn是公司未来的价值，“<<”代表“远小于”。价值投资和\n成长投资殊途同归，都是希望现在以五毛钱的价格购买未来价值一元钱的企业\n（P0<<Vn），两者的区别无非是企业的价值支撑的来源不同。成长投资的价值支\n撑主要来自企业未来收入和利润的高增长，更强调公司未来的价值Vn要远大于公\n司现在的价值V0，但这种投资需要预测未来的远见，只有极少数的人能够做到。\n价值投资的价值支撑主要来自企业现有资产、利润和现金流，更注重公司现在的\n价格P0是否远小于公司现在的价值V0，这种投资需要分析现在，难度相对较小，\n大多数人通过学习都能够掌握。\n不可否认，每个投资人都有自己的能力边界和局限性，但只要认识到了局限\n性的存在，就可以在一定程度上摆脱它的制约。我对自己的局限性是这样认识\n的：我更擅长总结过去的规律性的东西，而不擅长预测未来的突破和演变；我更\n擅长在变化中寻找不变，而不擅长在不变中寻找变化。意识到这种局限性的存在\n之后，我开始尽力寻找一些历史上被证明行之有效的简单法则、简单工具，然后\n长期坚持。\n比如，我把选股的要素简化为估值、品质和时机，并且淡化了时机的重要性\n（不是因为不重要，而是因为难把握），于是选股的复杂问题就变成了寻找“便\n宜的好公司”这个相对简单的问题。然后，针对不同的行业特性，利用波特五\n力、杜邦分析、估值分析等简单工具，弄清这个行业里决定竞争胜负的关键因素\n是什么、什么样的公司算“好公司”、什么样的价格是“便宜”。举例来说，对\n于餐饮业而言，回头客多、翻台率高、坪效高的就是“好公司”；对于连锁零售\n业而言，同店增长高、开店速度快、应收账款低的就是“好公司”；对于制造业\n而言，规模大、成本低、存货少的就是“好公司”。\n另外，我还努力奉行一些简单的原则，例如：\n第一，便宜才是硬道理。即使是普通公司，只要足够便宜，也会有丰厚的回\n报。A股市场鱼龙混杂，发现“价格合理的伟大公司”的难度远远超过寻找“价格\n被低估的普通公司”。\n第二，定价权是核心竞争力。有核心竞争力的公司有两个标准：一是做的是\n自己可以不断复制的事情，比如麦当劳和星巴克可以不断地跨区域开新店，在全\n世界成功复制；二是做的是别人不可能复制的事情，具备独占资源、品牌美誉\n度、专利、技术、寡头垄断地位、牌照准入限制等特征，最终体现为企业的定价\n权。\n第三，胜而后求战，不要战而后求胜。百舸争流的行业，增长再快也很难找\n投资标的，不妨等待行业“内战”结束、赢家产生后再做投资。许多人担心在胜\n负已分的行业中买赢家会太迟，其实腾讯、百度、格力、茅台等企业在十年前就\n已经是各自行业里的赢家了，但是十年来它们的涨幅依然惊人。\n第四，人弃我取，逆向投资。不论是巴菲特、索罗斯，还是邓普顿、卡尔·\n伊坎，投资领域的集大成者大多数都具有超强的逆向思维能力。A股的情绪波动容\n易走极端，任何概念和主题，无论真假，只要够新够炫，都能在短期内炒翻天，\n但是爆炒之后常是暴跌，因此对于如我这般手脚不快的人来说，“人多的地方不\n去”更是至理名言。\n以上这些都是很简单的法则和工具，所以不可能“总是对”、也不一定“马\n上对”，但是这些法则和工具都是经过许多成功投资人长期验证的、触及投资本\n质的、规律性的东西。这些规律性的东西虽然看起来是投资中最简单的事，却也\n是投资中最本质的东西，并不会因为时空的不同而产生大的差异——虽然每隔几\n年就会有一段时间，市场的狂热让人觉得“这次不同了”。15年来，我亲身经历\n过两次市场对价值投资的广泛质疑，一次是1999年纳斯达克泡沫的顶峰，另一次\n是2013年A股的创业板热潮。虽然两次质疑相隔了14年，但是其中的相似之处如此\n之多，以至于人们不得不感叹人性的亘古不变。虽然科学技术的进步日新月异，\n但是人性中不变的贪婪和恐惧，总能让那些认为“这次不同了”的观点，随着时\n间的推移被证明只不过是对历史的健忘。\n我想把这本书献给我的父亲邱华炳。父亲是位大学教师，一生潜心学术、著\n作等身，学生遍布金融、财税、经济的各个领域。因为父亲，我在成长之初就近\n距离地接触到许多之后的业界精英并向他们学习。不论是在专业还是生活上，父\n亲都是我不折不扣的启蒙老师，他总是教育我做事先做人，要常怀感恩之心，要\n多读书，不在于积累知识而在于培养能力。父亲去世已经十多年了，但是每次遇\n到他以前的学生，许多人依然清晰地记得父亲说过的话和言谈举止的细节，他们\n流露出来的真挚情感和深切怀念，总令我感动不已。本书的稿酬将全部捐给父亲\n生前从事的教育事业和关心的家乡公益事业。\n最后，要特别感谢高瓴资本的张磊先生百忙中为本书作序。张磊先生是我最\n钦佩的投资人，他对行业规律的深刻理解、对企业品质的深入剖析、对格局变化\n的前瞻性把握都是非常值得我学习的地方，他的序言无疑为本书增色许多。同\n时，我也衷心感谢巴曙松、詹余引、陈鸿桥、裘国根和赵丹阳等良师益友们拨冗\n为本书所写的推荐语。韩海峰做了许多协助文字整理的细致工作，在此一并致\n谢。另外，要特别感谢湛庐文化的精心编辑，使原本杂乱无章的众多内容升华成\n一本脉络清晰的书。\n谨以此书与所有的投资人共勉。由于本书由不同时间点所写的文章、随笔和\n演讲实录汇集而成，所作的一些判断和评论都带有鲜明的时间烙印和特定背景，\n请广大读者在阅读时注意甄别。由于作者水平有限，疏漏在所难免，不足之处，\n欢迎各方朋友们批评指正。\n邱国鹭\n2014年7月\n目录\n推荐序\n自 序\n第一部分 投资理念\n01 以实业的眼光做投资\n02 人弃我取，逆向投资的关键\n03 便宜是硬道理\n【投资随想录】\n硬币的两面\n遛狗理论\n个例与规律\n第二部分 投资方法\n04 投资的三个基本问题\n05 宁数月亮，不数星星\n06 经验就像旧衣服\n【投资随想录】\n扑克与投资\n投资眼光\n股票式债券\n第三部分 投资风险\n07 价值陷阱与成长陷阱\n08 真假风险与安全边际\n09 价值投资的局限性\n【投资随想录】\n往事如烟\n几句废话\n第四部分 投资策略\n10 四种周期、三种杠杆，行业轮动时机的把握\n11 未来10年：投资路在何方\n12 对冲中国：机遇与挑战\n【投资随想录】\n投资大白话\n国家竞争优势\n《美国士兵守则》的投资解读\n第五部分 投资心理学 投资心理学\n13 人性的弱点：投资者常见的心理误区\n14 后视镜\n15 傻瓜定价说\n16 这次不同了\n17 树动风动心动\n18 知易行难\n附录 投资访谈 投资访谈\n投资需要逆向思维\nA股市场是价值投资者的乐土\n“超额收益主要来自行业配置，国内啤酒业已至拐点”\n“狼性3号”：一种是跑得快的人，另一种是熬得住的人\n投资戒盲目，慎选“风口的猪”\n后 记\n\n\n\n\n\n听邱国鹭谈行业投资\n#护城河#\n每三四年就得重挖一次的护城河其实不能算是护城河，而没有护城河就不断会有前浪死在沙\n滩上。在一个先发优势不断被颠覆、没有永远的赢家的行业里，只有勇于自我否定、因时而\n变才能生存。\n#成长vs门槛#\n多数人喜欢成长，但我喜欢门槛。成长是未来的，难预测；门槛是既成的，易把握。高门槛\n行业，新进入者难存活，因此行业供给受限，竞争有序，有利于企业盈利增长。低门槛行\n业，行业供给增长快，无序竞争，谁也赚不到钱。（门槛，即行业护城河）\n#成长vs门槛：案例#\n白色家电行业2000—2005年增长迅速，但利润不佳，股价疲软；2006—2010年行业增速减\n缓，但利润大增，龙头股价上涨十几倍。拐点是2005年行业大洗牌，小厂退出，之后龙头企\n业在规模、渠道、成本、品牌等方面优势扩大，阻止了新进入者，行业格局从野蛮生长的无\n序竞争转变为有门槛的有序竞争。\n十几年前我刚进入基金业的时候，曾问过公司的一位资深合伙人，怎样才能\n成为一名优秀的基金经理。他说，其实很简单，你只要记住两条：第一，把客户\n的钱当作自己的钱来珍惜；第二，把二级市场的股票投资当作一级市场的实业投\n资来分析。\n这是不是一门好生意\n如果用自己的钱做实业投资，首先要考虑的问题就是：这是不是一门好生\n意。不过，二级市场有时就是偏爱“烂生意”。比如2013年市场上非常火爆的手\n机游戏行业，就是一门烂生意。\n根据艾瑞咨询的不完全统计，2012年仅在苹果的IOS平台上，就有3 883家公\n司推出的10 400款手机游戏，如果再加上安卓平台就更是不计其数了。但在这么\n多的游戏当中，月流水过千万的却屈指可数。\n即使你行大运做出了一款火爆的游戏，产品的生命周期一般也只有3~6个月，\n之后你就得推出新产品。而事实上，在数千家游戏开发商中，能够连续推出两款\n火爆游戏的实在是凤毛麟角。目前绝大多数的手机游戏是单机游戏，单机游戏的\n特点就是产品生命短，这一点和网页游戏很像。事实表明，页游行业的内容开发\n方很难做大，只是市场选择对此视而不见罢了。\n手游不像端游那样有较好的用户黏度，一款重度端游可以火个五年十年，靠\n的是在游戏中建立起的一种深度互动的、牢固的社会关系。但是，社交游戏也不\n能保证自身的持续性，就像Facebook上曾经一统江湖的Zynga，过去这一年多股\n价暴跌80%。几年前，火得不能再火的偷瓜偷菜游戏也是熟人之间的社交游戏，但\n是火过一阵子也就销声匿迹了，这样的商业模式你怎么能给出高估值呢？他今年\n赚的钱再多，你怎么能够知道三五年后这家公司是否还能像现在一样红火呢？而\n且，手机游戏内容开发商的议价权其实是很有限的，主要的钱都被平台商赚走\n了。\n大家都想成为平台，但是，要成为一个平台又谈何容易？苹果系统只有一个\n平台，安卓平台最后成功的可能也只有两三个，再加上腾讯的微信平台，铁定又\n要分流走很多游戏玩家。在这样的形势下，手机游戏开发商其实只能是“人为刀\n俎，我为鱼肉”，让平台把百分之七八十的收入分走。\n人们只看到7亿手机用户这个巨大的市场，却忽视了这其实是个竞争无比激\n烈、一将功成万骨枯的行业。人们只看到成功的“一将”，选择性地忽视了“枯\n了的万骨”。任何公司只要跟手游沾点边就能够被爆炒，甚至连旅游公司推出个\n手机自助游软件也能够受到市场的追捧。市场的非理性可见一斑。\n投资微论\n长期牛股 什么行业易出长期牛股？行业集中度持续提高的行业。因为这\n样的行业有门槛，有先发优势，后浪没法让前浪死在沙滩上，易出大牛股。\n相反，如果行业越来越分散，说明行业门槛不高，既有的领先者没有足够深\n的护城河来阻止追赶者抢夺其市场份额，这种行业一般是城头变幻大王旗，\n各领风骚两三年。\n企业的商业模式和现金流状况\n用自己的钱做实业投资要考虑的第二个问题，就是这门生意的现金流状况如\n何，毕竟做生意的最终目的是赚取现金流。\n2013年受市场热捧的电影行业其实是个现金流状况很差的行业。中国每年会\n拍七百多部电影，只有两百多部能够上映，其中票房能够超过五亿的屈指可数。\n即使赚了五亿的票房“大获成功”的电影，扣除分给院线的一半，再扣除发行费\n宣传费，制片方能够拿到手的大概只有2亿多一点。再扣除给编剧、导演、制片和\n演员的薪酬以及拍摄中的各种成本，最后剩下的净利润可能只有几千万。\n更麻烦的是，从现金流的角度看，拍电影得先写剧本，然后请导演、搭班\n子、雇演员，支出一大笔费用，一年半载之后影片开始发行、宣传，又是一大笔\n费用，而且电影公映之后要等好几个月才能从票房中分到钱。所以很多电影公司\n不管利润怎样，现金流都是大幅为负，抗风险能力特别弱，一有风吹草动就容易\n元气大伤。\n不论是美国的百年老店米高梅，还是后起之秀梦工厂，只要有一片大制作成\n了票房毒药，就逃脱不了破产和被收购的命运。美国的电影业发展了上百年，居\n然没有一家独立的电影公司，全都只是大型的综合传媒集团的一部分，这也体现\n了电影作为一个独立的商业模式的内在缺陷。\n另外，电影的定价权掌握在导演和演员手里，观众买票到电影院是去看范冰\n冰、徐峥和冯小刚的，不是去看电影公司的，所以名导演和名演员的薪酬总能涨\n到让电影制片方不怎么赚钱的水平。就好比欧洲的足坛，虽然球星拥有天价收\n入，俱乐部却在亏损，原因很简单：定价权在球星手里。迪士尼能够历经百年屹\n立不倒，很重要的原因是米老鼠和唐老鸭不会要求涨片酬。\n用自己的钱做实业投资的人，除了些另有所图的暴发户以外，很少有人会真\n金白银地砸重金投资电影，因为这是个现金流很差、不确定性很高的行业。A股的\n电影公司动辄两三百亿市值，但是与他们相同体量的在美股上市的中国电影公司\n的市值却只有15亿人民币，两者相差十几倍。\n我们再来比较一下房地产公司的商业模式，北上广深随便卖栋别墅都是几千\n万利润，顶得上一部好电影了。拍电影不一定每部都能火，而别墅几乎每栋都卖\n得掉。再从现金流的角度看，地产公司只要出钱拍了地，挖个坑、做个沙盘就可\n以预售了，客户会排着队把钱交上，他用你的钱盖你的房子，自己对现金流的要\n求其实并不高（盲目高价拿地的除外）。\n投资微论\n好公司的两个标准 一是它做的事情别人做不了；二是它做的事情自己可\n以重复做。前者是门槛，决定利润率的高低和趋势；后者是成长的可复制\n性，决定销售增速。如果二者不可兼得，宁要有门槛的低增长（可持续），\n也不要没门槛的高增长（不可持续）。门槛是现有的，好把握；成长是将来\n的，难预测。\n行业的竞争格', '2026-05-15 18:53:56');
INSERT INTO `study_quiz` (`id`, `node_id`, `stem`, `options_json`, `answer`, `analysis`, `sort`) VALUES (3000, 1010, '某团队试图让系统自动识别垃圾邮件,他们提供了大量历史邮件样本,但未编写任何过滤关键词。这符合哪种范式?', '[{\"key\":\"A\",\"text\":\"机器学习范式\"},{\"key\":\"B\",\"text\":\"传统编程范式\"},{\"key\":\"C\",\"text\":\"混合处理范式\"},{\"key\":\"D\",\"text\":\"人工审核范式\"}]', 'A', '正确答案是 A。根据材料,机器学习范式下人类不再编写规则(如过滤关键词),而是提供大量经验数据(历史邮件样本),由算法寻找模式。B 选项需要显式编写规则,与题意相反;C 和 D 选项材料未提及。', 0);
INSERT INTO `study_quiz` (`id`, `node_id`, `stem`, `options_json`, `answer`, `analysis`, `sort`) VALUES (3001, 1010, '机器学习中,\"模型\"最准确的描述是?', '[{\"key\":\"A\",\"text\":\"程序员编写的一组 if-else 规则\"},{\"key\":\"B\",\"text\":\"从大量经验数据中归纳出来、可用于新预测的产物\"},{\"key\":\"C\",\"text\":\"原始的训练数据集本身\"},{\"key\":\"D\",\"text\":\"评估系统好坏的指标公式\"}]', 'B', '模型是学习算法基于数据产出的\"压缩规则\",可用于对新输入做出预测。', 1);
