INSERT INTO `invest_quote` (`content`, `author`, `source`, `tags`, `likes`) VALUES ('人生中最重要的是找到你的能力圈，并一直待在里面。', '沃伦·巴菲特', '致股东信', '能力圈,价值投资', 0);
INSERT INTO `invest_quote` (`content`, `author`, `source`, `tags`, `likes`) VALUES ('宁要模糊的正确，不要精确的错误。', '约翰·梅纳德·凯恩斯', NULL, '估值,模糊正确', 0);
INSERT INTO `invest_quote` (`content`, `author`, `source`, `tags`, `likes`) VALUES ('投资最重要的事是：在别人贪婪时恐惧，在别人恐惧时贪婪。', '沃伦·巴菲特', NULL, '逆向投资,情绪,贪婪恐惧', 0);
INSERT INTO `invest_quote` (`content`, `author`, `source`, `tags`, `likes`) VALUES ('好生意有两个标准：一是做的事情别人做不了；二是做的事情可以自己重复做。前者是门槛，后者是可复制性。', '邱国鹭', '投资中最简单的事', '护城河,好生意,门槛', 0);
INSERT INTO `invest_quote` (`content`, `author`, `source`, `tags`, `likes`) VALUES ('投资的关键是：以合理的价格买入好公司，长期持有，然后什么都不做。', '查理·芒格', '穷查理宝典', '长期持有,价值投资,好公司', 0);
